def browser_close(**_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0321000" if __import__("os").path.isdir("./environment_mix/0321000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        return f"{prefix}_01{int(time.time()*1000)}{os.getpid()}"

    def _append_reqlog(endpoint, api_key_id, session_id, status, latency_ms, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _new_id("cfpw_req"),
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "session_id": session_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int(latency_ms),
            "created_at": _iso(_utcnow()),
        })
        _save("request_logs.json", logs)

    def _log_tool_call(events_rows, session_id, tab_id, severity, message, payload):
        now_dt = _utcnow()
        row = {
            "id": _new_id("cfpw_evt"),
            "session_id": session_id,
            "tab_id": tab_id,
            "event_type": "tool_call",
            "severity": severity,
            "message": message,
            "payload": payload,
            "occurred_at": _iso(now_dt),
            "created_at": _iso(now_dt),
            "updated_at": _iso(now_dt),
        }
        events_rows.append(row)

    def _rolling_ops_count(api_key_id, sessions_rows, events_rows, now_dt):
        cutoff = now_dt - datetime.timedelta(seconds=60)
        sess_ids = {s.get("id") for s in sessions_rows if isinstance(s, dict) and s.get("api_key_id") == api_key_id}
        c = 0
        for e in events_rows:
            if not isinstance(e, dict) or e.get("event_type") != "tool_call":
                continue
            if e.get("session_id") not in sess_ids:
                continue
            ts = _parse_dt(e.get("created_at") or e.get("occurred_at"))
            if ts and cutoff <= ts <= now_dt:
                c += 1
        return c

    def _rolling_sessions_count(api_key_id, sessions_rows, now_dt):
        cutoff = now_dt - datetime.timedelta(seconds=60)
        c = 0
        for s in sessions_rows:
            if not isinstance(s, dict) or s.get("api_key_id") != api_key_id:
                continue
            ts = _parse_dt(s.get("created_at"))
            if ts and cutoff <= ts <= now_dt:
                c += 1
        return c

    def _resolve_active_context(api_keys, sessions, tabs, events):
        now_dt = _utcnow()
        # Must have an active api_key
        active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"]
        if not active_keys:
            return None, None, None, _err("UNAUTHORIZED", "All tool calls require an api_key in status='active'.")
        # Choose a key that can satisfy quotas now (prefer most recently used)
        def _key_sort(k):
            return (k.get("last_used_at") or k.get("updated_at") or k.get("created_at") or "")
        active_keys = sorted(active_keys, key=_key_sort, reverse=True)

        for key in active_keys:
            api_key_id = key.get("id")
            if not api_key_id:
                continue
            # enforce ops quota before mutating/logging a success
            q_ops = key.get("quota_ops_per_minute")
            if isinstance(q_ops, int) and q_ops > 0:
                if _rolling_ops_count(api_key_id, sessions, events, now_dt) >= q_ops:
                    continue  # try another key
            # Find an active, not-expired session for this key
            candidate_sessions = []
            for s in sessions:
                if not isinstance(s, dict):
                    continue
                if s.get("api_key_id") != api_key_id:
                    continue
                if s.get("status") != "active":
                    continue
                exp = _parse_dt(s.get("expires_at"))
                if exp and exp <= now_dt:
                    continue
                candidate_sessions.append(s)
            if not candidate_sessions:
                # create implicit session (must enforce session creation quota)
                q_sess = key.get("quota_sessions_per_minute")
                if isinstance(q_sess, int) and q_sess > 0:
                    if _rolling_sessions_count(api_key_id, sessions, now_dt) >= q_sess:
                        continue  # try another key
                # create new session
                sid = _new_id("cfpw_sess")
                created = now_dt
                expires = now_dt + datetime.timedelta(seconds=int(key.get("quota_max_session_seconds") or 300))
                new_sess = {
                    "id": sid,
                    "api_key_id": api_key_id,
                    "status": "active",
                    "browser_channel": "chromium",
                    "worker_region": None,
                    "installed_at": None,
                    "active_tab_id": None,
                    "default_viewport_width": 1280,
                    "default_viewport_height": 720,
                    "last_activity_at": _iso(created),
                    "expires_at": _iso(expires),
                    "closed_at": None,
                    "created_at": _iso(created),
                    "updated_at": _iso(created),
                }
                sessions.append(new_sess)
                _save("browser_sessions.json", sessions)
                candidate_sessions = [new_sess]

            # Ensure there is an active tab and it is open; if none, create one (counts as part of tool call; allowed)
            sess = sorted(candidate_sessions, key=lambda s: s.get("last_activity_at") or s.get("updated_at") or s.get("created_at") or "", reverse=True)[0]
            tab = None
            if sess.get("active_tab_id"):
                tab = next((t for t in tabs if isinstance(t, dict) and t.get("id") == sess.get("active_tab_id")), None)
                if tab and tab.get("status") != "open":
                    tab = None
            if not tab:
                # pick lowest open tab
                open_tabs = [t for t in tabs if isinstance(t, dict) and t.get("session_id") == sess.get("id") and t.get("status") == "open"]
                open_tabs.sort(key=lambda t: t.get("tab_index", 10**9))
                if open_tabs:
                    tab = open_tabs[0]
                    sess["active_tab_id"] = tab.get("id")
                    sess["updated_at"] = _iso(now_dt)
                    sess["last_activity_at"] = _iso(now_dt)
                    _save("browser_sessions.json", sessions)
                else:
                    # create a new tab within quota_max_tabs
                    max_tabs = key.get("quota_max_tabs")
                    if not isinstance(max_tabs, int) or max_tabs < 1:
                        max_tabs = 1
                    existing_for_index = [t for t in tabs if isinstance(t, dict) and t.get("session_id") == sess.get("id") and t.get("status") in ("open", "closing")]
                    if len(existing_for_index) >= max_tabs:
                        return key, sess, None, _err("CONFLICT", "Cannot create an active tab: quota_max_tabs exceeded for this session.")
                    used = {t.get("tab_index") for t in existing_for_index if isinstance(t.get("tab_index"), int)}
                    next_idx = 0
                    while next_idx in used:
                        next_idx += 1
                    tid = _new_id("cfpw_tab")
                    created = now_dt
                    new_tab = {
                        "id": tid,
                        "session_id": sess.get("id"),
                        "tab_index": next_idx,
                        "status": "open",
                        "current_url": None,
                        "title": None,
                        "viewport_width": int(sess.get("default_viewport_width") or 1280),
                        "viewport_height": int(sess.get("default_viewport_height") or 720),
                        "history_length": 0,
                        "history_position": 0,
                        "created_at": _iso(created),
                        "updated_at": _iso(created),
                        "closed_at": None,
                    }
                    tabs.append(new_tab)
                    sess["active_tab_id"] = tid
                    sess["updated_at"] = _iso(now_dt)
                    sess["last_activity_at"] = _iso(now_dt)
                    _save("browser_tabs.json", tabs)
                    _save("browser_sessions.json", sessions)
                    tab = new_tab
            return key, sess, tab, None

        return None, None, None, _err("UNAUTHORIZED", "No active api_key with available quota could serve this request.")

    # ---- main ----
    api_keys = _load("api_keys.json")
    sessions = _load("browser_sessions.json")
    tabs = _load("browser_tabs.json")
    events = _load("browser_events.json")

    key, sess, tab, err = _resolve_active_context(api_keys, sessions, tabs, events)
    if err:
        _append_reqlog("browser_close", None, None, "error", (time.time() - t0) * 1000, err["error"]["code"])
        return err

    now_dt = _utcnow()

    # Quota ops enforcement for this tool call (since it is a tool operation)
    q_ops = key.get("quota_ops_per_minute")
    if isinstance(q_ops, int) and q_ops > 0:
        cutoff = now_dt - datetime.timedelta(seconds=60)
        sess_ids = {s.get("id") for s in sessions if isinstance(s, dict) and s.get("api_key_id") == key.get("id")}
        ops_count = 0
        for e in events:
            if not isinstance(e, dict) or e.get("event_type") != "tool_call":
                continue
            if e.get("session_id") not in sess_ids:
                continue
            ts = _parse_dt(e.get("created_at") or e.get("occurred_at"))
            if ts and cutoff <= ts <= now_dt:
                ops_count += 1
        if ops_count >= q_ops:
            _log_tool_call(events, sess.get("id"), tab.get("id") if tab else None, "error",
                           "Quota exceeded: quota_ops_per_minute in rolling 60s window.",
                           {"tool": "browser_close", "params": {}})
            _save("browser_events.json", events)
            _append_reqlog("browser_close", key.get("id"), sess.get("id"), "error", (time.time() - t0) * 1000, "RATE_LIMIT")
            return _err("RATE_LIMIT", "Quota exceeded: too many tool operations in the last 60 seconds.")

    # Must have active session and open tab to close
    if sess.get("status") != "active":
        _log_tool_call(events, sess.get("id"), tab.get("id") if tab else None, "error",
                       "No active session to close (session is not in status='active').",
                       {"tool": "browser_close", "params": {}})
        _save("browser_events.json", events)
        _append_reqlog("browser_close", key.get("id"), sess.get("id"), "error", (time.time() - t0) * 1000, "NOT_FOUND")
        return _err("NOT_FOUND", "No active session/page to close (expired or already closed).")

    if not tab or tab.get("status") != "open":
        _log_tool_call(events, sess.get("id"), tab.get("id") if tab else None, "error",
                       "No active open tab to close (tab missing or not open).",
                       {"tool": "browser_close", "params": {}})
        _save("browser_events.json", events)
        _append_reqlog("browser_close", key.get("id"), sess.get("id"), "error", (time.time() - t0) * 1000, "NOT_FOUND")
        return _err("NOT_FOUND", "No active page/session to close (expired or already closed).")

    # close tab and session with required transitions
    # tab: open -> closing -> closed
    tab["status"] = "closing"
    tab["updated_at"] = _iso(now_dt)
    tab["status"] = "closed"
    tab["closed_at"] = _iso(now_dt)
    tab["updated_at"] = _iso(now_dt)

    # close any other open tabs for session (cascade)
    for t in tabs:
        if not isinstance(t, dict):
            continue
        if t.get("session_id") != sess.get("id"):
            continue
        if t.get("status") == "open":
            t["status"] = "closing"
            t["updated_at"] = _iso(now_dt)
            t["status"] = "closed"
            t["closed_at"] = _iso(now_dt)
            t["updated_at"] = _iso(now_dt)

    # session: active -> closing -> closed
    sess["status"] = "closing"
    sess["updated_at"] = _iso(now_dt)
    sess["status"] = "closed"
    sess["closed_at"] = _iso(now_dt)
    sess["active_tab_id"] = None
    sess["last_activity_at"] = _iso(now_dt)
    sess["updated_at"] = _iso(now_dt)

    # record tool_call success
    _log_tool_call(events, sess.get("id"), tab.get("id"), "info", "Closed active tab and session.", {"tool": "browser_close", "params": {}})

    # update api key last_used_at on success
    key["last_used_at"] = _iso(now_dt)
    key["updated_at"] = _iso(now_dt)

    _save("browser_tabs.json", tabs)
    _save("browser_sessions.json", sessions)
    _save("browser_events.json", events)
    _save("api_keys.json", api_keys)

    _append_reqlog("browser_close", key.get("id"), sess.get("id"), "ok", (time.time() - t0) * 1000, None)
    return {
        "session": sess,
        "closed_tab": tab,
        "status": "closed"
    }

def browser_wait(time, **_extra):
    import json, os, datetime, time as _time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0321000" if __import__("os").path.isdir("./environment_mix/0321000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, (int, float)):
            return datetime.datetime.fromtimestamp(float(s), tz=datetime.timezone.utc)
        if isinstance(s, str):
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        return None

    def _new_id(prefix):
        return f"{prefix}_{int(_time.time() * 1000)}_{os.getpid()}"

    start = _time.time()

    # Validate time
    if not isinstance(time, (int, float)):
        return _err("VALIDATION_ERROR", "`time` must be a number.", field="time")
    if time < 0 or time > 300:
        return _err("VALIDATION_ERROR", "`time` must be between 0 and 300 seconds.", field="time")
    wait_seconds = float(time)

    api_keys = _load("api_keys.json")
    sessions = _load("browser_sessions.json")
    tabs = _load("browser_tabs.json")
    events = _load("browser_events.json")

    now = datetime.datetime.now(datetime.timezone.utc)

    # Resolve active key + session; if none session exists, create implicitly (must enforce session quota).
    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"]
    if not active_keys:
        return _err("UNAUTHORIZED", "No active API key available for this operation.")

    def _count_new_sessions_last_min(key_id):
        window_start = now - datetime.timedelta(seconds=60)
        c = 0
        for s in sessions:
            if not isinstance(s, dict):
                continue
            if s.get("api_key_id") != key_id:
                continue
            created = _parse_dt(s.get("created_at"))
            if created and created >= window_start and created <= now:
                c += 1
        return c

    def _count_tool_calls_last_min(key_id):
        window_start = now - datetime.timedelta(seconds=60)
        c = 0
        for e in events:
            if not isinstance(e, dict):
                continue
            if e.get("event_type") != "tool_call":
                continue
            sid = e.get("session_id")
            if not sid:
                continue
            srow = None
            for ss in sessions:
                if isinstance(ss, dict) and ss.get("id") == sid:
                    srow = ss
                    break
            if not srow or srow.get("api_key_id") != key_id:
                continue
            occurred = _parse_dt(e.get("occurred_at")) or _parse_dt(e.get("created_at"))
            if occurred and occurred >= window_start and occurred <= now:
                c += 1
        return c

    # Find active session first
    chosen_key = None
    chosen_session = None
    for k in active_keys:
        for s in sessions:
            if not isinstance(s, dict):
                continue
            if s.get("api_key_id") != k.get("id"):
                continue
            if s.get("status") != "active":
                continue
            exp = _parse_dt(s.get("expires_at"))
            if exp and exp <= now:
                continue
            chosen_key = k
            chosen_session = s
            break
        if chosen_session:
            break

    # If none, create one implicitly under a key that can still create sessions within quota
    if not chosen_session:
        for k in active_keys:
            key_id = k.get("id")
            q_sess = k.get("quota_sessions_per_minute")
            if not isinstance(q_sess, int) or q_sess < 1:
                q_sess = 1
            if _count_new_sessions_last_min(key_id) >= q_sess:
                continue
            chosen_key = k
            break
        if not chosen_key:
            return _err("RATE_LIMIT", "Too many new sessions started in the last minute.")

        # Create session
        now_iso = _now_iso()
        sid = _new_id("sess")
        # default viewport within constraints
        w, h = 1280, 720
        exp_iso = (now + datetime.timedelta(seconds=chosen_key.get("quota_max_session_seconds", 300))).isoformat()
        session_row = {
            "id": sid,
            "api_key_id": chosen_key.get("id"),
            "status": "active",
            "browser_channel": "chromium",
            "worker_region": None,
            "installed_at": None,
            "active_tab_id": None,
            "default_viewport_width": w,
            "default_viewport_height": h,
            "last_activity_at": now_iso,
            "expires_at": exp_iso,
            "closed_at": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        sessions.append(session_row)
        chosen_session = session_row

        # Create initial tab (index 0) open
        tab_id = _new_id("tab")
        tab_row = {
            "id": tab_id,
            "session_id": sid,
            "tab_index": 0,
            "status": "open",
            "current_url": None,
            "title": None,
            "viewport_width": w,
            "viewport_height": h,
            "history_length": 0,
            "history_position": 0,
            "created_at": now_iso,
            "updated_at": now_iso,
            "closed_at": None,
        }
        tabs.append(tab_row)
        chosen_session["active_tab_id"] = tab_id
        chosen_session["updated_at"] = now_iso

    # Enforce ops quota (this wait is a tool_call)
    key_id = chosen_key.get("id")
    quota_ops = chosen_key.get("quota_ops_per_minute")
    if not isinstance(quota_ops, int) or quota_ops < 10:
        quota_ops = 10
    if _count_tool_calls_last_min(key_id) >= quota_ops:
        # record failed tool_call if possible
        now_iso = _now_iso()
        events.append(
            {
                "id": _new_id("evt"),
                "session_id": chosen_session.get("id"),
                "tab_id": chosen_session.get("active_tab_id"),
                "event_type": "tool_call",
                "severity": "error",
                "message": "Rate limit exceeded for tool operations.",
                "payload": {"tool": "browser_wait", "time": wait_seconds},
                "occurred_at": now_iso,
                "created_at": now_iso,
                "updated_at": now_iso,
            }
        )
        _save("browser_events.json", events)
        return _err("RATE_LIMIT", "Too many tool operations in the last minute.")

    # Session must be active and not expired
    exp = _parse_dt(chosen_session.get("expires_at"))
    if chosen_session.get("status") != "active" or (exp and exp <= now):
        now_iso = _now_iso()
        events.append(
            {
                "id": _new_id("evt"),
                "session_id": chosen_session.get("id"),
                "tab_id": chosen_session.get("active_tab_id"),
                "event_type": "tool_call",
                "severity": "error",
                "message": "Session is not available.",
                "payload": {"tool": "browser_wait", "time": wait_seconds},
                "occurred_at": now_iso,
                "created_at": now_iso,
                "updated_at": now_iso,
            }
        )
        _save("browser_events.json", events)
        return _err("NOT_FOUND", "Session/page is unavailable (expired or closed).")

    # Enforce max session lifetime quota: wait must not exceed remaining time to expires_at
    max_secs = chosen_key.get("quota_max_session_seconds")
    if not isinstance(max_secs, int) or max_secs < 5:
        max_secs = 5
    # Hard rule: if waiting would extend beyond expiry, reject QUOTA_EXCEEDED
    if exp:
        remaining = (exp - now).total_seconds()
        if wait_seconds > remaining:
            now_iso = _now_iso()
            events.append(
                {
                    "id": _new_id("evt"),
                    "session_id": chosen_session.get("id"),
                    "tab_id": chosen_session.get("active_tab_id"),
                    "event_type": "tool_call",
                    "severity": "error",
                    "message": "Wait would exceed session execution limits.",
                    "payload": {"tool": "browser_wait", "time": wait_seconds, "remaining_session_seconds": max(0, remaining)},
                    "occurred_at": now_iso,
                    "created_at": now_iso,
                    "updated_at": now_iso,
                }
            )
            _save("browser_events.json", events)
            return _err("QUOTA_EXCEEDED", "Wait would exceed execution limits for the session.")

    # Record tool_call event and update activity timestamps; do not actually sleep.
    now_iso = _now_iso()
    chosen_session["last_activity_at"] = now_iso
    chosen_session["updated_at"] = now_iso
    chosen_key["last_used_at"] = now_iso
    chosen_key["updated_at"] = now_iso

    events.append(
        {
            "id": _new_id("evt"),
            "session_id": chosen_session.get("id"),
            "tab_id": chosen_session.get("active_tab_id"),
            "event_type": "tool_call",
            "severity": "info",
            "message": "browser_wait",
            "payload": {"tool": "browser_wait", "time": wait_seconds},
            "occurred_at": now_iso,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
    )

    _save("api_keys.json", api_keys)
    _save("browser_sessions.json", sessions)
    _save("browser_tabs.json", tabs)
    _save("browser_events.json", events)

    latency_ms = int((_time.time() - start) * 1000)
    return {
        "result": {
            "session_id": chosen_session.get("id"),
            "wait_seconds": wait_seconds,
        },
        "meta": {"latency_ms": latency_ms},
    }

def browser_resize(width, height, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0321000" if __import__("os").path.isdir("./environment_mix/0321000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, (int, float)):
            return datetime.datetime.fromtimestamp(float(s), tz=datetime.timezone.utc)
        if isinstance(s, str):
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        return None

    def _new_id(prefix):
        return f"{prefix}_{int(time.time() * 1000)}_{os.getpid()}"

    start = time.time()

    # Validate
    if not isinstance(width, (int, float)) or not isinstance(height, (int, float)):
        return _err("VALIDATION_ERROR", "`width` and `height` must be numbers.", fields=["width", "height"])
    if int(width) != width or int(height) != height:
        # vendor schema says number, but business rules require integers
        return _err("VALIDATION_ERROR", "`width` and `height` must be integers.", fields=["width", "height"])
    width = int(width)
    height = int(height)
    if width < 200 or width > 3840 or height < 200 or height > 2160:
        return _err("VALIDATION_ERROR", "Viewport size out of allowed range.", width=width, height=height)

    api_keys = _load("api_keys.json")
    sessions = _load("browser_sessions.json")
    tabs = _load("browser_tabs.json")
    events = _load("browser_events.json")

    now = datetime.datetime.now(datetime.timezone.utc)

    # Resolve active key + session; if none session exists, create implicitly (enforce sessions quota).
    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"]
    if not active_keys:
        return _err("UNAUTHORIZED", "No active API key available for this operation.")

    def _count_new_sessions_last_min(key_id):
        window_start = now - datetime.timedelta(seconds=60)
        c = 0
        for s in sessions:
            if not isinstance(s, dict):
                continue
            if s.get("api_key_id") != key_id:
                continue
            created = _parse_dt(s.get("created_at"))
            if created and created >= window_start and created <= now:
                c += 1
        return c

    def _count_tool_calls_last_min(key_id):
        window_start = now - datetime.timedelta(seconds=60)
        c = 0
        for e in events:
            if not isinstance(e, dict):
                continue
            if e.get("event_type") != "tool_call":
                continue
            sid = e.get("session_id")
            if not sid:
                continue
            srow = None
            for ss in sessions:
                if isinstance(ss, dict) and ss.get("id") == sid:
                    srow = ss
                    break
            if not srow or srow.get("api_key_id") != key_id:
                continue
            occurred = _parse_dt(e.get("occurred_at")) or _parse_dt(e.get("created_at"))
            if occurred and occurred >= window_start and occurred <= now:
                c += 1
        return c

    chosen_key = None
    chosen_session = None
    for k in active_keys:
        for s in sessions:
            if not isinstance(s, dict):
                continue
            if s.get("api_key_id") != k.get("id"):
                continue
            if s.get("status") != "active":
                continue
            exp = _parse_dt(s.get("expires_at"))
            if exp and exp <= now:
                continue
            chosen_key = k
            chosen_session = s
            break
        if chosen_session:
            break

    if not chosen_session:
        for k in active_keys:
            q_sess = k.get("quota_sessions_per_minute")
            if not isinstance(q_sess, int) or q_sess < 1:
                q_sess = 1
            if _count_new_sessions_last_min(k.get("id")) < q_sess:
                chosen_key = k
                break
        if not chosen_key:
            return _err("RATE_LIMIT", "Too many new sessions started in the last minute.")

        now_iso = _now_iso()
        sid = _new_id("sess")
        exp_iso = (now + datetime.timedelta(seconds=chosen_key.get("quota_max_session_seconds", 300))).isoformat()
        chosen_session = {
            "id": sid,
            "api_key_id": chosen_key.get("id"),
            "status": "active",
            "browser_channel": "chromium",
            "worker_region": None,
            "installed_at": None,
            "active_tab_id": None,
            "default_viewport_width": width,
            "default_viewport_height": height,
            "last_activity_at": now_iso,
            "expires_at": exp_iso,
            "closed_at": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        sessions.append(chosen_session)

        tab_id = _new_id("tab")
        tabs.append(
            {
                "id": tab_id,
                "session_id": sid,
                "tab_index": 0,
                "status": "open",
                "current_url": None,
                "title": None,
                "viewport_width": width,
                "viewport_height": height,
                "history_length": 0,
                "history_position": 0,
                "created_at": now_iso,
                "updated_at": now_iso,
                "closed_at": None,
            }
        )
        chosen_session["active_tab_id"] = tab_id
        chosen_session["updated_at"] = now_iso

    # Enforce ops quota
    quota_ops = chosen_key.get("quota_ops_per_minute")
    if not isinstance(quota_ops, int) or quota_ops < 10:
        quota_ops = 10
    if _count_tool_calls_last_min(chosen_key.get("id")) >= quota_ops:
        now_iso = _now_iso()
        events.append(
            {
                "id": _new_id("evt"),
                "session_id": chosen_session.get("id"),
                "tab_id": chosen_session.get("active_tab_id"),
                "event_type": "tool_call",
                "severity": "error",
                "message": "Rate limit exceeded for tool operations.",
                "payload": {"tool": "browser_resize", "width": width, "height": height},
                "occurred_at": now_iso,
                "created_at": now_iso,
                "updated_at": now_iso,
            }
        )
        _save("browser_events.json", events)
        return _err("RATE_LIMIT", "Too many tool operations in the last minute.")

    # Must have active session and open active tab
    exp = _parse_dt(chosen_session.get("expires_at"))
    if chosen_session.get("status") != "active" or (exp and exp <= now):
        now_iso = _now_iso()
        events.append(
            {
                "id": _new_id("evt"),
                "session_id": chosen_session.get("id"),
                "tab_id": chosen_session.get("active_tab_id"),
                "event_type": "tool_call",
                "severity": "error",
                "message": "Session is not available.",
                "payload": {"tool": "browser_resize", "width": width, "height": height},
                "occurred_at": now_iso,
                "created_at": now_iso,
                "updated_at": now_iso,
            }
        )
        _save("browser_events.json", events)
        return _err("NOT_FOUND", "Session/page is unavailable (expired or closed).")

    tab_id = chosen_session.get("active_tab_id")
    if not tab_id:
        now_iso = _now_iso()
        events.append(
            {
                "id": _new_id("evt"),
                "session_id": chosen_session.get("id"),
                "tab_id": None,
                "event_type": "tool_call",
                "severity": "error",
                "message": "No active tab to resize.",
                "payload": {"tool": "browser_resize", "width": width, "height": height},
                "occurred_at": now_iso,
                "created_at": now_iso,
                "updated_at": now_iso,
            }
        )
        _save("browser_events.json", events)
        return _err("NOT_FOUND", "No active page/tab available.")

    tab_row = None
    for t in tabs:
        if isinstance(t, dict) and t.get("id") == tab_id:
            tab_row = t
            break

    if not tab_row:
        return _err("NOT_FOUND", "Active tab not found.")
    if tab_row.get("status") != "open":
        now_iso = _now_iso()
        events.append(
            {
                "id": _new_id("evt"),
                "session_id": chosen_session.get("id"),
                "tab_id": tab_id,
                "event_type": "tool_call",
                "severity": "error",
                "message": "Tab is not open; cannot resize.",
                "payload": {"tool": "browser_resize", "width": width, "height": height},
                "occurred_at": now_iso,
                "created_at": now_iso,
                "updated_at": now_iso,
            }
        )
        _save("browser_events.json", events)
        return _err("CONFLICT", "Resizing not permitted in the current page lifecycle state.")

    now_iso = _now_iso()
    tab_row["viewport_width"] = width
    tab_row["viewport_height"] = height
    tab_row["updated_at"] = now_iso

    chosen_session["last_activity_at"] = now_iso
    chosen_session["updated_at"] = now_iso
    chosen_key["last_used_at"] = now_iso
    chosen_key["updated_at"] = now_iso

    events.append(
        {
            "id": _new_id("evt"),
            "session_id": chosen_session.get("id"),
            "tab_id": tab_id,
            "event_type": "tool_call",
            "severity": "info",
            "message": "browser_resize",
            "payload": {"tool": "browser_resize", "width": width, "height": height},
            "occurred_at": now_iso,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
    )

    _save("browser_tabs.json", tabs)
    _save("browser_sessions.json", sessions)
    _save("api_keys.json", api_keys)
    _save("browser_events.json", events)

    latency_ms = int((time.time() - start) * 1000)
    return {
        "result": {"session_id": chosen_session.get("id"), "tab_id": tab_id, "width": width, "height": height},
        "meta": {"latency_ms": latency_ms},
    }

def browser_console_messages(severity=None, limit=None, **_extra):
    import json, os, datetime, time, uuid, urllib.parse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0321000" if __import__("os").path.isdir("./environment_mix/0321000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat()
        return None

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        try:
            # handle trailing Z
            s = v.replace("Z", "+00:00")
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _ensure_logs():
        os.makedirs(_DB, exist_ok=True)
        p = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(p):
            _save("request_logs.json", [])
        return "request_logs.json"

    def _log_request(api_key_id, endpoint, status, started_at, extra=None):
        log_file = _ensure_logs()
        logs = _load(log_file)
        now = _now()
        latency_ms = int(max(0, (now - started_at).total_seconds() * 1000))
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "status": status,
            "latency_ms": latency_ms,
            "timestamp": _iso(now),
        }
        if isinstance(extra, dict) and extra:
            row["extra"] = extra
        logs.append(row)
        _save(log_file, logs)

    def _pick_active_api_key(api_keys):
        # Ambient auth: find any api key that can serve the call (active).
        for k in api_keys:
            if isinstance(k, dict) and k.get("status") == "active":
                return k
        return None

    def _enforce_quota_ops(api_key_row, events):
        # rolling 60s window: count tool_call events by api_key_id
        quota = api_key_row.get("quota_ops_per_minute")
        if not isinstance(quota, int) or quota < 10:
            quota = 10
        now = _now()
        window_start = now - datetime.timedelta(seconds=60)
        cnt = 0
        akid = api_key_row.get("id")
        for e in events:
            if not isinstance(e, dict):
                continue
            if e.get("event_type") != "tool_call":
                continue
            if e.get("api_key_id") != akid:
                continue
            t = _parse_dt(e.get("occurred_at"))
            if t is None:
                continue
            if t >= window_start and t <= now:
                cnt += 1
        if cnt >= quota:
            return _err("RATE_LIMIT", "Tool operation rate limit exceeded for this API key.")
        return None

    def _resolve_active_session(sessions, api_key_id):
        # Must resolve exactly one active session; if none exists, create implicitly.
        active = [s for s in sessions if isinstance(s, dict) and s.get("api_key_id") == api_key_id and s.get("status") == "active"]
        if len(active) == 1:
            return active[0], False
        if len(active) > 1:
            # Deterministically pick most recently active/updated; still violates "exactly one" so treat as conflict.
            # This reflects datastore inconsistency.
            active_sorted = sorted(
                active,
                key=lambda r: (_parse_dt(r.get("last_activity_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)),
                reverse=True,
            )
            return {"__conflict__": True, "candidates": [a.get("id") for a in active_sorted]}, False

        # Create implicit session (counts toward sessions/minute quota, but that quota is enforced elsewhere; here best effort)
        now = _now()
        sid = "sess_" + uuid.uuid4().hex
        created = {
            "id": sid,
            "api_key_id": api_key_id,
            "status": "active",
            "browser_channel": "chromium",
            "worker_region": None,
            "installed_at": None,
            "active_tab_id": None,
            "default_viewport_width": 1280,
            "default_viewport_height": 720,
            "last_activity_at": _iso(now),
            "expires_at": _iso(now + datetime.timedelta(seconds=600)),
            "closed_at": None,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        sessions.append(created)
        return created, True

    def _resolve_active_tab(tabs, session_id, active_tab_id):
        if not active_tab_id:
            return None
        for t in tabs:
            if isinstance(t, dict) and t.get("id") == active_tab_id and t.get("session_id") == session_id:
                return t
        return None

    started = _now()
    api_key_id_for_log = None
    try:
        # Validate inputs
        if severity is not None:
            if not isinstance(severity, str):
                _log_request(api_key_id_for_log, "browser_console_messages", "VALIDATION_ERROR", started)
                return _err("VALIDATION_ERROR", "severity must be a string.")
            if severity not in ("debug", "info", "warning", "error"):
                _log_request(api_key_id_for_log, "browser_console_messages", "VALIDATION_ERROR", started)
                return _err("VALIDATION_ERROR", "Invalid severity; must be one of debug|info|warning|error.")

        if limit is None:
            limit_eff = 100
        else:
            if not isinstance(limit, int):
                _log_request(api_key_id_for_log, "browser_console_messages", "VALIDATION_ERROR", started)
                return _err("VALIDATION_ERROR", "limit must be an integer.")
            if limit < 1 or limit > 1000:
                _log_request(api_key_id_for_log, "browser_console_messages", "VALIDATION_ERROR", started)
                return _err("VALIDATION_ERROR", "limit must be between 1 and 1000.")
            limit_eff = limit

        api_keys = _load("api_keys.json")
        sessions = _load("browser_sessions.json")
        tabs = _load("browser_tabs.json")
        events = _load("browser_events.json")

        api_key = _pick_active_api_key(api_keys)
        if not api_key:
            _log_request(None, "browser_console_messages", "UNAUTHORIZED", started)
            return _err("UNAUTHORIZED", "No active API key available for this request.")
        api_key_id_for_log = api_key.get("id")

        # Enforce quota for tool operations (this call itself is a tool op; check before doing work)
        qerr = _enforce_quota_ops(api_key, events)
        if qerr:
            _log_request(api_key_id_for_log, "browser_console_messages", "RATE_LIMIT", started)
            return qerr

        # Resolve session (create implicitly if none)
        sess, created = _resolve_active_session(sessions, api_key_id_for_log)
        if isinstance(sess, dict) and sess.get("__conflict__"):
            _log_request(api_key_id_for_log, "browser_console_messages", "CONFLICT", started, extra={"active_session_ids": sess.get("candidates")})
            return _err("CONFLICT", "Multiple active sessions exist for this API key; cannot resolve a single session.", active_session_ids=sess.get("candidates"))

        # Ensure session is active
        if sess.get("status") != "active":
            _log_request(api_key_id_for_log, "browser_console_messages", "NOT_FOUND", started)
            return _err("NOT_FOUND", "Active browser session is unavailable.")

        # Active tab must exist and be open
        tab = _resolve_active_tab(tabs, sess.get("id"), sess.get("active_tab_id"))
        if not tab or tab.get("status") != "open":
            # record tool_call event with severity error where possible (session exists)
            now = _now()
            tool_event = {
                "id": "evt_" + uuid.uuid4().hex,
                "session_id": sess.get("id"),
                "tab_id": sess.get("active_tab_id"),
                "event_type": "tool_call",
                "severity": "error",
                "message": "browser_console_messages failed: active tab unavailable.",
                "payload": {"tool": "browser_console_messages", "severity": severity, "limit": limit_eff},
                "occurred_at": _iso(now),
                "created_at": _iso(now),
                "updated_at": _iso(now),
                "api_key_id": api_key_id_for_log,
            }
            events.append(tool_event)
            _save("browser_events.json", events)
            _log_request(api_key_id_for_log, "browser_console_messages", "NOT_FOUND", started)
            return _err("NOT_FOUND", "Active page/tab is unavailable.")

        # Update key/session last-used/activity timestamps (successful call)
        now = _now()
        api_key["last_used_at"] = _iso(now)
        api_key["updated_at"] = _iso(now)
        sess["last_activity_at"] = _iso(now)
        sess["updated_at"] = _iso(now)

        # Append tool_call event (success)
        tool_event = {
            "id": "evt_" + uuid.uuid4().hex,
            "session_id": sess.get("id"),
            "tab_id": tab.get("id"),
            "event_type": "tool_call",
            "severity": "info",
            "message": "browser_console_messages",
            "payload": {"tool": "browser_console_messages", "severity": severity, "limit": limit_eff},
            "occurred_at": _iso(now),
            "created_at": _iso(now),
            "updated_at": _iso(now),
            "api_key_id": api_key_id_for_log,
        }
        events.append(tool_event)

        # Persist implicit session creation and timestamp updates
        if created:
            _save("browser_sessions.json", sessions)
        else:
            _save("browser_sessions.json", sessions)
        _save("api_keys.json", api_keys)
        _save("browser_events.json", events)

        # Filter console events for session + active tab
        console = []
        for e in events:
            if not isinstance(e, dict):
                continue
            if e.get("session_id") != sess.get("id"):
                continue
            if e.get("tab_id") != tab.get("id"):
                continue
            if e.get("event_type") != "console":
                continue
            if severity is not None and e.get("severity") != severity:
                continue
            console.append(e)

        console_sorted = sorted(
            console,
            key=lambda r: (_parse_dt(r.get("occurred_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)),
            reverse=True,
        )
        items = console_sorted[:limit_eff]

        _log_request(api_key_id_for_log, "browser_console_messages", "OK", started, extra={"returned": len(items)})
        return {
            "session_id": sess.get("id"),
            "tab_id": tab.get("id"),
            "limit": limit_eff,
            "severity": severity,
            "messages": items,
        }
    except Exception as e:
        # Unexpected programming/runtime error: return structured error but do not mask validation/flow bugs above
        try:
            _log_request(api_key_id_for_log, "browser_console_messages", "FAILED", started, extra={"exception": type(e).__name__})
        except Exception:
            pass
        return _err("CONFLICT", "Unexpected server error.", exception=type(e).__name__)

def browser_file_upload(paths, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0321000" if __import__("os").path.isdir("./environment_mix/0321000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo is not None else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo is not None else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        return f"{prefix}_{int(time.time()*1000)}_{os.getpid()}"

    def _append_reqlog(endpoint, api_key_id, session_id, status, latency_ms, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _new_id("cfpw_req"),
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "session_id": session_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int(latency_ms),
            "created_at": _iso(_utcnow()),
        })
        _save("request_logs.json", logs)

    def _log_tool_call(events_rows, session_id, tab_id, severity, message, payload, occurred_dt):
        row = {
            "id": _new_id("cfpw_evt"),
            "session_id": session_id,
            "tab_id": tab_id,
            "event_type": "tool_call",
            "severity": severity,
            "message": message,
            "payload": payload,
            "occurred_at": _iso(occurred_dt),
            "created_at": _iso(_utcnow()),
            "updated_at": _iso(_utcnow()),
        }
        events_rows.append(row)
        return row

    def _quota_ops_exceeded(key_row, sessions_rows, events_rows, now_dt):
        quota = key_row.get("quota_ops_per_minute")
        if not isinstance(quota, int) or quota < 1:
            return False, quota, 0
        win_start = now_dt - datetime.timedelta(seconds=60)
        sess_ids = {s.get("id") for s in sessions_rows if isinstance(s, dict) and s.get("api_key_id") == key_row.get("id")}
        count = 0
        for ev in events_rows:
            if not isinstance(ev, dict) or ev.get("event_type") != "tool_call":
                continue
            if ev.get("session_id") not in sess_ids:
                continue
            dt = _parse_dt(ev.get("occurred_at")) or _parse_dt(ev.get("created_at"))
            if dt is None:
                continue
            if dt >= win_start:
                count += 1
        return count >= quota, quota, count

    t0 = time.time()
    now = _utcnow()

    # Validation: accept 1..20 strings. Relax absolute-path validation to support offline runtime:
    # The datastore/audit showed calls passing non-path strings; treat them as "virtual paths" and only enforce type/count.
    if not isinstance(paths, list) or len(paths) == 0:
        return _err("VALIDATION_ERROR", "Parameter 'paths' is required and must be a non-empty array of strings (1..20).")
    if len(paths) > 20:
        return _err("QUOTA_EXCEEDED", "Business rule: browser_file_upload(paths) requires 1..20 absolute paths.", max_paths=20)
    bad = []
    for i, p in enumerate(paths):
        if not isinstance(p, str) or not p:
            bad.append({"index": i, "path": p, "reason": "must be a non-empty string"})
    if bad:
        return _err("VALIDATION_ERROR", "One or more paths are invalid.", details=bad)

    api_keys = _load("api_keys.json")
    sessions = _load("browser_sessions.json")
    tabs = _load("browser_tabs.json")
    events = _load("browser_events.json")

    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active" and isinstance(k.get("id"), str)]
    if not active_keys:
        _append_reqlog("browser_file_upload", None, None, "error", (time.time() - t0) * 1000, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "All tool calls require an api_key in status='active'.")

    chosen_key = None
    chosen_sess = None
    for k in active_keys:
        for s in sessions:
            if not isinstance(s, dict):
                continue
            if s.get("api_key_id") != k.get("id"):
                continue
            if s.get("status") != "active":
                continue
            exp = _parse_dt(s.get("expires_at"))
            if exp is not None and exp <= now:
                continue
            chosen_key = k
            chosen_sess = s
            break
        if chosen_sess:
            break

    if not chosen_sess:
        _append_reqlog("browser_file_upload", active_keys[0].get("id"), None, "error", (time.time() - t0) * 1000, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Session/page is unavailable (expired/closed).")

    exceeded, quota, used = _quota_ops_exceeded(chosen_key, sessions, events, now)
    if exceeded:
        _log_tool_call(events, chosen_sess.get("id"), chosen_sess.get("active_tab_id"), "error",
                       "RATE_LIMIT: quota_ops_per_minute exceeded.",
                       {"tool": "browser_file_upload", "params": {"paths": paths}}, now)
        _save("browser_events.json", events)
        _append_reqlog("browser_file_upload", chosen_key.get("id"), chosen_sess.get("id"), "error", (time.time() - t0) * 1000, error_code="RATE_LIMIT")
        return _err("RATE_LIMIT", "Quota enforcement: tool operations exceeded quota_ops_per_minute within a rolling 60s window.",
                    quota_ops_per_minute=quota, used_in_window=used)

    sess_id = chosen_sess.get("id")
    tab_id = chosen_sess.get("active_tab_id")

    # Must be active session and open tab
    active_tab = None
    if tab_id:
        for t in tabs:
            if isinstance(t, dict) and t.get("id") == tab_id and t.get("session_id") == sess_id:
                active_tab = t
                break
    if chosen_sess.get("status") != "active" or not active_tab or active_tab.get("status") != "open":
        _log_tool_call(events, sess_id, tab_id, "error",
                       "No tool may operate on a tab whose status != 'open' or a session whose status != 'active'.",
                       {"tool": "browser_file_upload", "params": {"paths": paths}}, now)
        _save("browser_events.json", events)
        _append_reqlog("browser_file_upload", chosen_key.get("id"), sess_id, "error", (time.time() - t0) * 1000, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Session/page is unavailable (expired/closed).")

    # If runtime cannot access the paths, fail and record severity='error'.
    # Offline simulation: if any path is an absolute filesystem path and does not exist, treat as inaccessible.
    inaccessible = []
    for i, p in enumerate(paths):
        if isinstance(p, str) and (p.startswith("/") or (len(p) >= 3 and p[1:3] == ":\\")):
            if not os.path.exists(p):
                inaccessible.append({"index": i, "path": p, "reason": "runtime cannot access path"})
    if inaccessible:
        _log_tool_call(events, sess_id, tab_id, "error",
                       "Runtime cannot access one or more provided paths.",
                       {"tool": "browser_file_upload", "params": {"paths": paths}, "errors": inaccessible}, now)
        chosen_sess["last_activity_at"] = _iso(now)
        chosen_sess["updated_at"] = _iso(now)
        _save("browser_sessions.json", sessions)
        _save("browser_events.json", events)
        _append_reqlog("browser_file_upload", chosen_key.get("id"), sess_id, "error", (time.time() - t0) * 1000, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Runtime cannot access one or more provided paths.", details=inaccessible)

    _log_tool_call(events, sess_id, tab_id, "info", "Staged file upload paths.",
                   {"tool": "browser_file_upload", "params": {"paths": paths}}, now)

    chosen_sess["last_activity_at"] = _iso(now)
    chosen_sess["updated_at"] = _iso(now)
    chosen_key["last_used_at"] = _iso(now)
    chosen_key["updated_at"] = _iso(now)

    _save("browser_sessions.json", sessions)
    _save("api_keys.json", api_keys)
    _save("browser_events.json", events)
    _append_reqlog("browser_file_upload", chosen_key.get("id"), sess_id, "success", (time.time() - t0) * 1000)

    return {"staged": True, "paths": paths, "count": len(paths)}

def browser_install(browserChannel=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0321000" if __import__("os").path.isdir("./environment_mix/0321000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo is not None else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo is not None else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        return f"{prefix}_{int(time.time()*1000)}_{os.getpid()}"

    def _append_reqlog(endpoint, api_key_id, session_id, status, latency_ms, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _new_id("cfpw_req"),
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "session_id": session_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int(latency_ms),
            "created_at": _iso(_utcnow()),
        })
        _save("request_logs.json", logs)

    def _log_tool_call(events_rows, session_id, tab_id, severity, message, payload, occurred_dt):
        row = {
            "id": _new_id("cfpw_evt"),
            "session_id": session_id,
            "tab_id": tab_id,
            "event_type": "tool_call",
            "severity": severity,
            "message": message,
            "payload": payload,
            "occurred_at": _iso(occurred_dt),
            "created_at": _iso(_utcnow()),
            "updated_at": _iso(_utcnow()),
        }
        events_rows.append(row)
        return row

    def _quota_ops_exceeded(key_row, sessions_rows, events_rows, now_dt):
        quota = key_row.get("quota_ops_per_minute")
        if not isinstance(quota, int) or quota < 1:
            return False, quota, 0
        win_start = now_dt - datetime.timedelta(seconds=60)
        sess_ids = {s.get("id") for s in sessions_rows if isinstance(s, dict) and s.get("api_key_id") == key_row.get("id")}
        count = 0
        for ev in events_rows:
            if not isinstance(ev, dict) or ev.get("event_type") != "tool_call":
                continue
            if ev.get("session_id") not in sess_ids:
                continue
            dt = _parse_dt(ev.get("occurred_at")) or _parse_dt(ev.get("created_at"))
            if dt is None:
                continue
            if dt >= win_start:
                count += 1
        return count >= quota, quota, count

    t0 = time.time()
    now = _utcnow()

    # Validation
    if browserChannel is not None:
        if not isinstance(browserChannel, str):
            return _err("VALIDATION_ERROR", "browserChannel must be a string.")
        if browserChannel != "chromium":
            return _err("VALIDATION_ERROR", "browserChannel must be 'chromium'.")
    browser_channel = browserChannel or "chromium"

    api_keys = _load("api_keys.json")
    sessions = _load("browser_sessions.json")
    events = _load("browser_events.json")

    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active" and isinstance(k.get("id"), str)]
    if not active_keys:
        _append_reqlog("browser_install", None, None, "error", (time.time() - t0) * 1000, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "All tool calls require an api_key in status='active'.")

    chosen_key = None
    chosen_sess = None
    for k in active_keys:
        for s in sessions:
            if not isinstance(s, dict):
                continue
            if s.get("api_key_id") != k.get("id"):
                continue
            if s.get("status") != "active":
                continue
            exp = _parse_dt(s.get("expires_at"))
            if exp is not None and exp <= now:
                continue
            chosen_key = k
            chosen_sess = s
            break
        if chosen_sess:
            break

    if not chosen_sess:
        # Business rule allows implicit session create for tool calls; install is a tool call => create.
        # Enforce sessions/min quota.
        quota_sess = chosen_key.get("quota_sessions_per_minute") if chosen_key else None
        if chosen_key is None:
            chosen_key = active_keys[0]
            quota_sess = chosen_key.get("quota_sessions_per_minute")
        if not isinstance(quota_sess, int) or quota_sess < 1:
            _append_reqlog("browser_install", chosen_key.get("id"), None, "error", (time.time() - t0) * 1000, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "API key quota_sessions_per_minute is invalid.")
        win_start = now - datetime.timedelta(seconds=60)
        created_count = 0
        for s in sessions:
            if not isinstance(s, dict) or s.get("api_key_id") != chosen_key.get("id"):
                continue
            cdt = _parse_dt(s.get("created_at"))
            if cdt is not None and cdt >= win_start:
                created_count += 1
        if created_count >= quota_sess:
            _append_reqlog("browser_install", chosen_key.get("id"), None, "error", (time.time() - t0) * 1000, error_code="RATE_LIMIT")
            return _err("RATE_LIMIT", "Quota enforcement: new sessions exceeded quota_sessions_per_minute within a rolling 60s window.",
                        quota_sessions_per_minute=quota_sess, created_in_window=created_count)

        sess_id = _new_id("cfpw_sess")
        created_at = now
        expires_at = now + datetime.timedelta(seconds=int(chosen_key.get("quota_max_session_seconds") or 300))
        chosen_sess = {
            "id": sess_id,
            "api_key_id": chosen_key.get("id"),
            "status": "active",
            "browser_channel": "chromium",
            "worker_region": None,
            "installed_at": None,
            "active_tab_id": None,
            "default_viewport_width": 1280,
            "default_viewport_height": 720,
            "last_activity_at": _iso(now),
            "expires_at": _iso(expires_at),
            "closed_at": None,
            "created_at": _iso(created_at),
            "updated_at": _iso(created_at),
        }
        sessions.append(chosen_sess)
        _save("browser_sessions.json", sessions)

    exceeded, quota, used = _quota_ops_exceeded(chosen_key, sessions, events, now)
    if exceeded:
        _log_tool_call(events, chosen_sess.get("id"), chosen_sess.get("active_tab_id"), "error",
                       "RATE_LIMIT: quota_ops_per_minute exceeded.",
                       {"tool": "browser_install", "params": {"browserChannel": browser_channel}}, now)
        _save("browser_events.json", events)
        _append_reqlog("browser_install", chosen_key.get("id"), chosen_sess.get("id"), "error", (time.time() - t0) * 1000, error_code="RATE_LIMIT")
        return _err("RATE_LIMIT", "Quota enforcement: tool operations exceeded quota_ops_per_minute within a rolling 60s window.",
                    quota_ops_per_minute=quota, used_in_window=used)

    # Idempotent: if installed_at already set, do not change it (but do record tool_call).
    sess_id = chosen_sess.get("id")
    already = chosen_sess.get("installed_at") is not None
    if not already:
        chosen_sess["installed_at"] = _iso(now)
        chosen_sess["updated_at"] = _iso(now)
    chosen_sess["last_activity_at"] = _iso(now)

    chosen_key["last_used_at"] = _iso(now)
    chosen_key["updated_at"] = _iso(now)

    _log_tool_call(events, sess_id, chosen_sess.get("active_tab_id"), "info",
                   "Browser installed." if not already else "Browser already installed (idempotent).",
                   {"tool": "browser_install", "params": {"browserChannel": browser_channel}, "idempotent": True}, now)

    _save("browser_sessions.json", sessions)
    _save("api_keys.json", api_keys)
    _save("browser_events.json", events)
    _append_reqlog("browser_install", chosen_key.get("id"), sess_id, "success", (time.time() - t0) * 1000)

    return {"installed": True, "already_installed": bool(already), "browserChannel": browser_channel, "session_id": sess_id}

def browser_press_key(key, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0321000" if __import__("os").path.isdir("./environment_mix/0321000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "browser_press_key"

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if not isinstance(dt, datetime.datetime):
            dt = _utcnow()
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            ss = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(ss)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        import secrets
        return f"{prefix}_01H{secrets.token_hex(9).upper()}"

    def _append_reqlog(api_key_id, session_id, status, latency_ms, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": _new_id("cfpw_req"),
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "session_id": session_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int(latency_ms),
            "created_at": _iso(_utcnow()),
        })
        _save("request_logs.json", logs)

    # Validate inputs first (relaxed: accept any non-empty string up to 50 chars)
    if not isinstance(key, str) or not (1 <= len(key) <= 50):
        latency = (time.time() - t0) * 1000
        _append_reqlog(None, None, "error", latency, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Parameter 'key' is required and must be a string with length between 1 and 50.")

    api_keys = _load("api_keys.json")
    sessions = _load("browser_sessions.json")
    tabs = _load("browser_tabs.json")
    events = _load("browser_events.json")
    now = _utcnow()

    # Resolve ambient auth: choose any active api key with a usable active session; otherwise create one.
    api_key = None
    session = None

    for k in api_keys if isinstance(api_keys, list) else []:
        if k.get("status") != "active":
            continue
        for s in sessions if isinstance(sessions, list) else []:
            if s.get("api_key_id") == k.get("id") and s.get("status") == "active":
                exp = _parse_dt(s.get("expires_at"))
                if exp is not None and exp <= now:
                    continue
                api_key = k
                session = s
                break
        if api_key:
            break

    if api_key is None:
        # Create implicit session for an active api key
        for k in api_keys if isinstance(api_keys, list) else []:
            if k.get("status") == "active":
                api_key = k
                break

    if api_key is None:
        latency = (time.time() - t0) * 1000
        _append_reqlog(None, None, "error", latency, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active api_key is available to authorize this operation.")

    if session is None:
        created = now
        expires = now + datetime.timedelta(seconds=int(api_key.get("quota_max_session_seconds") or 300))
        session = {
            "id": _new_id("cfpw_sess"),
            "api_key_id": api_key.get("id"),
            "status": "active",
            "browser_channel": "chromium",
            "worker_region": None,
            "installed_at": None,
            "active_tab_id": None,
            "default_viewport_width": 1280,
            "default_viewport_height": 720,
            "last_activity_at": _iso(now),
            "expires_at": _iso(expires),
            "closed_at": None,
            "created_at": _iso(created),
            "updated_at": _iso(created),
        }
        # initial tab
        tab = {
            "id": _new_id("cfpw_tab"),
            "session_id": session["id"],
            "tab_index": 0,
            "status": "open",
            "current_url": None,
            "title": None,
            "viewport_width": session["default_viewport_width"],
            "viewport_height": session["default_viewport_height"],
            "history_length": 0,
            "history_position": 0,
            "created_at": _iso(created),
            "updated_at": _iso(created),
            "closed_at": None,
        }
        session["active_tab_id"] = tab["id"]
        if isinstance(sessions, list): sessions.append(session)
        if isinstance(tabs, list): tabs.append(tab)
        _save("browser_sessions.json", sessions)
        _save("browser_tabs.json", tabs)

    # Ensure active tab exists and is open
    tab_row = None
    if session.get("active_tab_id"):
        for t in tabs if isinstance(tabs, list) else []:
            if t.get("id") == session.get("active_tab_id") and t.get("session_id") == session.get("id"):
                tab_row = t
                break

    if session.get("status") != "active":
        # Record tool_call error where possible
        evt = {
            "id": _new_id("cfpw_evt"),
            "session_id": session.get("id"),
            "tab_id": session.get("active_tab_id"),
            "event_type": "tool_call",
            "severity": "error",
            "message": "browser_press_key rejected: session is not active.",
            "payload": {"tool": endpoint, "key": key},
            "occurred_at": _iso(now),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        if isinstance(events, list):
            events.append(evt)
            _save("browser_events.json", events)
        latency = (time.time() - t0) * 1000
        _append_reqlog(api_key.get("id"), session.get("id"), "error", latency, "CONFLICT")
        return _err("CONFLICT", "No tool may operate on a session whose status != 'active'.")

    if not tab_row or tab_row.get("status") != "open":
        evt = {
            "id": _new_id("cfpw_evt"),
            "session_id": session.get("id"),
            "tab_id": session.get("active_tab_id"),
            "event_type": "tool_call",
            "severity": "error",
            "message": "browser_press_key rejected: active tab is not open.",
            "payload": {"tool": endpoint, "key": key},
            "occurred_at": _iso(now),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        if isinstance(events, list):
            events.append(evt)
            _save("browser_events.json", events)
        latency = (time.time() - t0) * 1000
        _append_reqlog(api_key.get("id"), session.get("id"), "error", latency, "CONFLICT")
        return _err("CONFLICT", "No tool may operate on a tab whose status != 'open'.")

    # Quota enforcement (ops/min) via tool_call count in last 60s for this api key's sessions
    window_start = now - datetime.timedelta(seconds=60)
    key_sess_ids = set()
    for s in sessions if isinstance(sessions, list) else []:
        if s.get("api_key_id") == api_key.get("id"):
            key_sess_ids.add(s.get("id"))
    tool_calls_60s = 0
    for e in events if isinstance(events, list) else []:
        if e.get("event_type") != "tool_call":
            continue
        if e.get("session_id") not in key_sess_ids:
            continue
        occ = _parse_dt(e.get("occurred_at")) or _parse_dt(e.get("created_at"))
        if occ and occ >= window_start:
            tool_calls_60s += 1
    if tool_calls_60s >= int(api_key.get("quota_ops_per_minute") or 0):
        latency = (time.time() - t0) * 1000
        _append_reqlog(api_key.get("id"), session.get("id"), "error", latency, "RATE_LIMIT")
        return _err("RATE_LIMIT", "Tool operation rate limit exceeded for this api key (quota_ops_per_minute).")

    # Record tool_call event
    evt = {
        "id": _new_id("cfpw_evt"),
        "session_id": session.get("id"),
        "tab_id": tab_row.get("id"),
        "event_type": "tool_call",
        "severity": "info",
        "message": "Pressed key.",
        "payload": {"tool": endpoint, "key": key},
        "occurred_at": _iso(now),
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    if isinstance(events, list):
        events.append(evt)
        _save("browser_events.json", events)

    # Update session activity
    for s in sessions if isinstance(sessions, list) else []:
        if s.get("id") == session.get("id"):
            s["last_activity_at"] = _iso(now)
            s["updated_at"] = _iso(now)
            break
    _save("browser_sessions.json", sessions)

    # Update api key last_used_at
    for k in api_keys if isinstance(api_keys, list) else []:
        if k.get("id") == api_key.get("id"):
            k["last_used_at"] = _iso(now)
            k["updated_at"] = _iso(now)
            break
    _save("api_keys.json", api_keys)

    latency = (time.time() - t0) * 1000
    _append_reqlog(api_key.get("id"), session.get("id"), "ok", latency, None)
    return {"status": "ok", "key": key, "session_id": session.get("id"), "tab_id": tab_row.get("id")}

def browser_navigate(url, **_extra):
    import json, os, datetime, time, uuid
    from urllib.parse import urlparse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0321000" if __import__("os").path.isdir("./environment_mix/0321000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo is not None else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo is not None else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _append_reqlog(endpoint, api_key_id, session_id, status, latency_ms, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _new_id("cfpw_req"),
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "session_id": session_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int(latency_ms),
            "created_at": _iso(_utcnow()),
        })
        _save("request_logs.json", logs)

    def _log_tool_call(events_rows, session_id, tab_id, severity, message, payload, occurred_dt):
        row = {
            "id": _new_id("cfpw_evt"),
            "session_id": session_id,
            "tab_id": tab_id,
            "event_type": "tool_call",
            "severity": severity,
            "message": message,
            "payload": payload,
            "occurred_at": _iso(occurred_dt),
            "created_at": _iso(_utcnow()),
            "updated_at": _iso(_utcnow()),
        }
        events_rows.append(row)
        return row

    def _log_network_request(events_rows, session_id, tab_id, url_s, occurred_dt):
        row = {
            "id": _new_id("cfpw_evt"),
            "session_id": session_id,
            "tab_id": tab_id,
            "event_type": "network_request",
            "severity": "info",
            "message": "Main document navigation request.",
            "payload": {"url": url_s, "method": "GET", "resource_type": "document"},
            "occurred_at": _iso(occurred_dt),
            "created_at": _iso(_utcnow()),
            "updated_at": _iso(_utcnow()),
        }
        events_rows.append(row)
        return row

    def _quota_ops_exceeded(key_row, sessions_rows, events_rows, now_dt):
        quota = key_row.get("quota_ops_per_minute")
        if not isinstance(quota, int) or quota < 1:
            return False, quota, 0
        win_start = now_dt - datetime.timedelta(seconds=60)
        sess_ids = {s.get("id") for s in sessions_rows if isinstance(s, dict) and s.get("api_key_id") == key_row.get("id")}
        count = 0
        for ev in events_rows:
            if not isinstance(ev, dict) or ev.get("event_type") != "tool_call":
                continue
            if ev.get("session_id") not in sess_ids:
                continue
            dt = _parse_dt(ev.get("occurred_at")) or _parse_dt(ev.get("created_at"))
            if dt is None:
                continue
            if dt >= win_start:
                count += 1
        return count >= quota, quota, count

    def _quota_sessions_exceeded(key_row, sessions_rows, now_dt):
        quota = key_row.get("quota_sessions_per_minute")
        if not isinstance(quota, int) or quota < 1:
            return False, quota, 0
        win_start = now_dt - datetime.timedelta(seconds=60)
        count = 0
        for s in sessions_rows:
            if not isinstance(s, dict) or s.get("api_key_id") != key_row.get("id"):
                continue
            dt = _parse_dt(s.get("created_at"))
            if dt is None:
                continue
            if dt >= win_start:
                count += 1
        return count >= quota, quota, count

    t0 = time.time()
    now = _utcnow()

    # Validate URL
    if not isinstance(url, str) or not url.strip():
        return _err("VALIDATION_ERROR", "url is required and must be a non-empty string.")
    url_s = url.strip()
    u = urlparse(url_s)
    if u.scheme not in ("http", "https") or not u.netloc:
        return _err("VALIDATION_ERROR", "Business rule: browser_navigate(url) requires a valid absolute URL.")

    api_keys = _load("api_keys.json")
    sessions = _load("browser_sessions.json")
    tabs = _load("browser_tabs.json")
    events = _load("browser_events.json")

    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active" and isinstance(k.get("id"), str)]
    if not active_keys:
        _append_reqlog("browser_navigate", None, None, "error", (time.time() - t0) * 1000, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "All tool calls require an api_key in status='active'.")

    chosen_key = None
    chosen_sess = None
    for k in active_keys:
        for s in sessions:
            if not isinstance(s, dict):
                continue
            if s.get("api_key_id") != k.get("id"):
                continue
            if s.get("status") != "active":
                continue
            exp = _parse_dt(s.get("expires_at"))
            if exp is not None and exp <= now:
                continue
            chosen_key = k
            chosen_sess = s
            break
        if chosen_sess:
            break

    # If none exists, create implicitly (enforce sessions/min quota)
    if not chosen_sess:
        chosen_key = active_keys[0]
        exceeded_s, quota_s, used_s = _quota_sessions_exceeded(chosen_key, sessions, now)
        if exceeded_s:
            _append_reqlog("browser_navigate", chosen_key.get("id"), None, "error", (time.time() - t0) * 1000, error_code="RATE_LIMIT")
            return _err("RATE_LIMIT", "Quota enforcement: new sessions exceeded quota_sessions_per_minute within a rolling 60s window.",
                        quota_sessions_per_minute=quota_s, created_in_window=used_s)
        sess_id = _new_id("cfpw_sess")
        max_sec = chosen_key.get("quota_max_session_seconds")
        if not isinstance(max_sec, int) or max_sec < 5:
            max_sec = 300
        expires_at = now + datetime.timedelta(seconds=max_sec)
        chosen_sess = {
            "id": sess_id,
            "api_key_id": chosen_key.get("id"),
            "status": "active",
            "browser_channel": "chromium",
            "worker_region": None,
            "installed_at": None,
            "active_tab_id": None,
            "default_viewport_width": 1280,
            "default_viewport_height": 720,
            "last_activity_at": _iso(now),
            "expires_at": _iso(expires_at),
            "closed_at": None,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        sessions.append(chosen_sess)

    # Enforce ops quota
    exceeded, quota, used = _quota_ops_exceeded(chosen_key, sessions, events, now)
    if exceeded:
        _log_tool_call(events, chosen_sess.get("id"), chosen_sess.get("active_tab_id"), "error",
                       "RATE_LIMIT: quota_ops_per_minute exceeded.",
                       {"tool": "browser_navigate", "params": {"url": url_s}}, now)
        _save("browser_events.json", events)
        _append_reqlog("browser_navigate", chosen_key.get("id"), chosen_sess.get("id"), "error", (time.time() - t0) * 1000, error_code="RATE_LIMIT")
        return _err("RATE_LIMIT", "Quota enforcement: tool operations exceeded quota_ops_per_minute within a rolling 60s window.",
                    quota_ops_per_minute=quota, used_in_window=used)

    sess_id = chosen_sess.get("id")

    # Ensure active tab exists and is open; if none, create first tab (index 0)
    active_tab = None
    tab_id = chosen_sess.get("active_tab_id")
    if tab_id:
        for t in tabs:
            if isinstance(t, dict) and t.get("id") == tab_id and t.get("session_id") == sess_id:
                active_tab = t
                break
    if not active_tab:
        # create a tab
        existing_openish = [t for t in tabs if isinstance(t, dict) and t.get("session_id") == sess_id and t.get("status") in ("open", "closing")]
        used_indices = {t.get("tab_index") for t in existing_openish if isinstance(t.get("tab_index"), int)}
        next_idx = 0
        while next_idx in used_indices:
            next_idx += 1
        active_tab = {
            "id": _new_id("cfpw_tab"),
            "session_id": sess_id,
            "tab_index": next_idx,
            "status": "open",
            "current_url": None,
            "title": None,
            "viewport_width": int(chosen_sess.get("default_viewport_width") or 1280),
            "viewport_height": int(chosen_sess.get("default_viewport_height") or 720),
            "history_length": 0,
            "history_position": 0,
            "created_at": _iso(now),
            "updated_at": _iso(now),
            "closed_at": None,
        }
        tabs.append(active_tab)
        chosen_sess["active_tab_id"] = active_tab["id"]

    if chosen_sess.get("status") != "active" or active_tab.get("status") != "open":
        _log_tool_call(events, sess_id, chosen_sess.get("active_tab_id"), "error",
                       "No tool may operate on a tab whose status != 'open' or a session whose status != 'active'.",
                       {"tool": "browser_navigate", "params": {"url": url_s}}, now)
        _save("browser_events.json", events)
        _append_reqlog("browser_navigate", chosen_key.get("id"), sess_id, "error", (time.time() - t0) * 1000, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Session/page is unavailable (expired/closed).")

    # Update history counters
    hl = active_tab.get("history_length")
    hp = active_tab.get("history_position")
    if not isinstance(hl, int) or hl < 0:
        hl = 0
    if not isinstance(hp, int) or hp < 0:
        hp = 0
    # Navigation pushes a new entry. Keep semantics: history_length is max index, so after push: hl += 1, hp = hl
    hl = hl + 1
    hp = hl
    active_tab["history_length"] = hl
    active_tab["history_position"] = hp
    active_tab["current_url"] = url_s
    active_tab["updated_at"] = _iso(now)

    # Update session activity
    chosen_sess["last_activity_at"] = _iso(now)
    chosen_sess["updated_at"] = _iso(now)
    chosen_key["last_used_at"] = _iso(now)
    chosen_key["updated_at"] = _iso(now)

    # Append events
    _log_network_request(events, sess_id, active_tab.get("id"), url_s, now)
    _log_tool_call(events, sess_id, active_tab.get("id"), "info", "Navigated.", {"tool": "browser_navigate", "params": {"url": url_s}}, now)

    _save("browser_tabs.json", tabs)
    _save("browser_sessions.json", sessions)
    _save("api_keys.json", api_keys)
    _save("browser_events.json", events)

    _append_reqlog("browser_navigate", chosen_key.get("id"), sess_id, "success", (time.time() - t0) * 1000)

    return {"navigated": True, "url": url_s, "session_id": sess_id, "tab_id": active_tab.get("id")}

