                count += 1
        return count >= quota, quota, count

    t0 = time.time()
    now = _utcnow()

    api_keys = _load("api_keys.json")
    sessions = _load("browser_sessions.json")
    tabs = _load("browser_tabs.json")
    events = _load("browser_events.json")

    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active" and isinstance(k.get("id"), str)]
    if not active_keys:
        _append_reqlog("browser_navigate_forward", None, None, "error", (time.time() - t0) * 1000, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "All tool calls require an api_key in status='active'.")

    chosen_key = None
    chosen_sess = None
    for k in active_keys:
        for s in sessions:
            if not isinstance(s, dict):
                continue
            if s.get("api_key_id") != k.get("id"):
                continue
            if s.get("status") != "active":
                continue
            exp = _parse_dt(s.get("expires_at"))
            if exp is not None and exp <= now:
                continue
            chosen_key = k
            chosen_sess = s
            break
        if chosen_sess:
            break

    if not chosen_sess:
        _append_reqlog("browser_navigate_forward", active_keys[0].get("id"), None, "error", (time.time() - t0) * 1000, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Session/page is unavailable (expired/closed).")

    exceeded, quota, used = _quota_ops_exceeded(chosen_key, sessions, events, now)
    if exceeded:
        _log_tool_call(events, chosen_sess.get("id"), chosen_sess.get("active_tab_id"), "error",
                       "RATE_LIMIT: quota_ops_per_minute exceeded.",
                       {"tool": "browser_navigate_forward", "params": {}}, now)
        _save("browser_events.json", events)
        _append_reqlog("browser_navigate_forward", chosen_key.get("id"), chosen_sess.get("id"), "error", (time.time() - t0) * 1000, error_code="RATE_LIMIT")
        return _err("RATE_LIMIT", "Quota enforcement: tool operations exceeded quota_ops_per_minute within a rolling 60s window.",
                    quota_ops_per_minute=quota, used_in_window=used)

    sess_id = chosen_sess.get("id")
    tab_id = chosen_sess.get("active_tab_id")

    active_tab = None
    if tab_id:
        for t in tabs:
            if isinstance(t, dict) and t.get("id") == tab_id and t.get("session_id") == sess_id:
                active_tab = t
                break
    if chosen_sess.get("status") != "active" or not active_tab or active_tab.get("status") != "open":
        _log_tool_call(events, sess_id, tab_id, "error",
                       "No tool may operate on a tab whose status != 'open' or a session whose status != 'active'.",
                       {"tool": "browser_navigate_forward", "params": {}}, now)
        _save("browser_events.json", events)
        _append_reqlog("browser_navigate_forward", chosen_key.get("id"), sess_id, "error", (time.time() - t0) * 1000, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Session/page is unavailable (expired/closed).")

    hp = active_tab.get("history_position")
    hl = active_tab.get("history_length")
    if not isinstance(hp, int) or hp < 0:
        hp = 0
    if not isinstance(hl, int) or hl < 0:
        hl = 0

    if hp >= hl:
        _log_tool_call(events, sess_id, tab_id, "error", "No forward history entry.",
                       {"tool": "browser_navigate_forward", "params": {}}, now)
        _save("browser_events.json", events)
        _append_reqlog("browser_navigate_forward", chosen_key.get("id"), sess_id, "error", (time.time() - t0) * 1000, error_code="CONFLICT")
        return _err("CONFLICT", "Business rule: browser_navigate_forward requires history_position < history_length.")

    active_tab["history_position"] = hp + 1
    active_tab["updated_at"] = _iso(now)
    chosen_sess["last_activity_at"] = _iso(now)
    chosen_sess["updated_at"] = _iso(now)
    chosen_key["last_used_at"] = _iso(now)
    chosen_key["updated_at"] = _iso(now)

    _log_tool_call(events, sess_id, tab_id, "info", "Navigated forward.", {"tool": "browser_navigate_forward", "params": {}}, now)

    _save("browser_tabs.json", tabs)
    _save("browser_sessions.json", sessions)
    _save("api_keys.json", api_keys)
    _save("browser_events.json", events)
    _append_reqlog("browser_navigate_forward", chosen_key.get("id"), sess_id, "success", (time.time() - t0) * 1000)

    return {"navigated_forward": True, "history_position": active_tab.get("history_position"), "history_length": active_tab.get("history_length")}

def browser_network_requests(limit=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0321000" if __import__("os").path.isdir("./environment_mix/0321000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        return f"{prefix}_01{int(time.time()*1000)}{os.getpid()}"

    def _append_reqlog(endpoint, api_key_id, session_id, status, latency_ms, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _new_id("cfpw_req"),
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "session_id": session_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int(latency_ms),
            "created_at": _iso(_utcnow()),
        })
        _save("request_logs.json", logs)

    def _log_tool_call(events_rows, session_id, tab_id, severity, message, payload):
        now_dt = _utcnow()
        row = {
            "id": _new_id("cfpw_evt"),
            "session_id": session_id,
            "tab_id": tab_id,
            "event_type": "tool_call",
            "severity": severity,
            "message": message,
            "payload": payload,
            "occurred_at": _iso(now_dt),
            "created_at": _iso(now_dt),
            "updated_at": _iso(now_dt),
        }
        events_rows.append(row)

    # validate limit
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or not (1 <= limit <= 1000):
        _append_reqlog("browser_network_requests", None, None, "error", (time.time() - t0) * 1000, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 1000.")

    api_keys = _load("api_keys.json")
    sessions = _load("browser_sessions.json")
    tabs = _load("browser_tabs.json")
    events = _load("browser_events.json")

    now_dt = _utcnow()

    # resolve active key + active session + open active tab (create session implicitly if missing)
    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active" and k.get("id")]
    if not active_keys:
        _append_reqlog("browser_network_requests", None, None, "error", (time.time() - t0) * 1000, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "All tool calls require an api_key in status='active'.")

    def _rolling_ops_count(api_key_id):
        cutoff = now_dt - datetime.timedelta(seconds=60)
        sess_ids = {s.get("id") for s in sessions if isinstance(s, dict) and s.get("api_key_id") == api_key_id}
        c = 0
        for e in events:
            if not isinstance(e, dict) or e.get("event_type") != "tool_call":
                continue
            if e.get("session_id") not in sess_ids:
                continue
            ts = _parse_dt(e.get("created_at") or e.get("occurred_at"))
            if ts and cutoff <= ts <= now_dt:
                c += 1
        return c

    picked = None
    for k in sorted(active_keys, key=lambda r: (r.get("last_used_at") or r.get("updated_at") or r.get("created_at") or ""), reverse=True):
        q = k.get("quota_ops_per_minute")
        if isinstance(q, int) and q > 0 and _rolling_ops_count(k["id"]) >= q:
            continue
        picked = k
        break
    if not picked:
        _append_reqlog("browser_network_requests", None, None, "error", (time.time() - t0) * 1000, "RATE_LIMIT")
        return _err("RATE_LIMIT", "Quota exceeded: too many tool operations in the last 60 seconds.")
    api_key_id = picked["id"]

    sess = None
    for s in sessions:
        if not isinstance(s, dict):
            continue
        if s.get("api_key_id") != api_key_id or s.get("status") != "active":
            continue
        exp = _parse_dt(s.get("expires_at"))
        if exp and exp <= now_dt:
            continue
        sess = s
        break
    if not sess:
        # create implicit session (enforce session quota)
        cutoff = now_dt - datetime.timedelta(seconds=60)
        created_count = 0
        for s in sessions:
            if not isinstance(s, dict) or s.get("api_key_id") != api_key_id:
                continue
            ts = _parse_dt(s.get("created_at"))
            if ts and cutoff <= ts <= now_dt:
                created_count += 1
        q_sess = picked.get("quota_sessions_per_minute")
        if isinstance(q_sess, int) and q_sess > 0 and created_count >= q_sess:
            _append_reqlog("browser_network_requests", api_key_id, None, "error", (time.time() - t0) * 1000, "RATE_LIMIT")
            return _err("RATE_LIMIT", "Quota exceeded: too many new sessions in the last 60 seconds.")
        sid = _new_id("cfpw_sess")
        expires = now_dt + datetime.timedelta(seconds=int(picked.get("quota_max_session_seconds") or 300))
        sess = {
            "id": sid,
            "api_key_id": api_key_id,
            "status": "active",
            "browser_channel": "chromium",
            "worker_region": None,
            "installed_at": None,
            "active_tab_id": None,
            "default_viewport_width": 1280,
            "default_viewport_height": 720,
            "last_activity_at": _iso(now_dt),
            "expires_at": _iso(expires),
            "closed_at": None,
            "created_at": _iso(now_dt),
            "updated_at": _iso(now_dt),
        }
        sessions.append(sess)
        _save("browser_sessions.json", sessions)

    tab = None
    if sess.get("active_tab_id"):
        tab = next((t for t in tabs if isinstance(t, dict) and t.get("id") == sess.get("active_tab_id")), None)
        if tab and tab.get("status") != "open":
            tab = None
    if not tab:
        open_tabs = [t for t in tabs if isinstance(t, dict) and t.get("session_id") == sess.get("id") and t.get("status") == "open"]
        open_tabs.sort(key=lambda t: t.get("tab_index", 10**9))
        if open_tabs:
            tab = open_tabs[0]
            sess["active_tab_id"] = tab.get("id")
            sess["updated_at"] = _iso(now_dt)
            _save("browser_sessions.json", sessions)

    if not tab or tab.get("status") != "open" or sess.get("status") != "active":
        _log_tool_call(events, sess.get("id"), tab.get("id") if tab else None, "error",
                       "No active session/page available for network requests.",
                       {"tool": "browser_network_requests", "params": {"limit": limit}})
        _save("browser_events.json", events)
        _append_reqlog("browser_network_requests", api_key_id, sess.get("id"), "error", (time.time() - t0) * 1000, "NOT_FOUND")
        return _err("NOT_FOUND", "There is no active session/page available (expired or already closed).")

    # record tool call (reads are still tool operations per business rule)
    _log_tool_call(events, sess.get("id"), tab.get("id"), "info", "Listed network request events.", {"tool": "browser_network_requests", "params": {"limit": limit}})
    sess["last_activity_at"] = _iso(now_dt)
    sess["updated_at"] = _iso(now_dt)
    picked["last_used_at"] = _iso(now_dt)
    picked["updated_at"] = _iso(now_dt)

    # Filter network_request events for active tab
    net = []
    for e in events:
        if not isinstance(e, dict):
            continue
        if e.get("event_type") != "network_request":
            continue
        if e.get("session_id") != sess.get("id"):
            continue
        if e.get("tab_id") != tab.get("id"):
            continue
        net.append(e)

    net.sort(key=lambda e: _parse_dt(e.get("occurred_at") or e.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc))
    net = net[:limit]

    _save("browser_events.json", events)
    _save("browser_sessions.json", sessions)
    _save("api_keys.json", api_keys)

    _append_reqlog("browser_network_requests", api_key_id, sess.get("id"), "ok", (time.time() - t0) * 1000, None)
    return {"events": net, "count": len(net), "limit": limit}

