    # "render"
    art["byte_size"] = 1024
    art["storage_url"] = f"r2://cfpw/{art_id}.pdf"
    art["status"] = "ready"
    art["ready_at"] = _iso(now_dt)
    art["updated_at"] = _iso(now_dt)

    # record tool_call
    _log_tool_call(events, sess.get("id"), tab.get("id"), "info", "PDF saved.", {"tool": "browser_pdf_save", "params": {}, "artifact_id": art_id})

    # update session/key last_activity/last_used
    sess["last_activity_at"] = _iso(now_dt)
    sess["updated_at"] = _iso(now_dt)
    picked["last_used_at"] = _iso(now_dt)
    picked["updated_at"] = _iso(now_dt)

    _save("browser_artifacts.json", artifacts)
    _save("browser_events.json", events)
    _save("browser_sessions.json", sessions)
    _save("api_keys.json", api_keys)

    _append_reqlog("browser_pdf_save", api_key_id, sess.get("id"), "ok", (time.time() - t0) * 1000, None)
    return {"artifact": art}

