            "severity": severity,
            "message": message,
            "payload": payload,
            "occurred_at": _iso(now_dt),
            "created_at": _iso(now_dt),
            "updated_at": _iso(now_dt),
        }
        events_rows.append(row)

    api_keys = _load("api_keys.json")
    sessions = _load("browser_sessions.json")
    tabs = _load("browser_tabs.json")
    events = _load("browser_events.json")
    artifacts = _load("browser_artifacts.json")

    now_dt = _utcnow()

    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active" and k.get("id")]
    if not active_keys:
        _append_reqlog("browser_snapshot", None, None, "error", (time.time() - t0) * 1000, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "All tool calls require an api_key in status='active'.")

    def _rolling_ops_count(api_key_id):
        cutoff = now_dt - datetime.timedelta(seconds=60)
        sess_ids = {s.get("id") for s in sessions if isinstance(s, dict) and s.get("api_key_id") == api_key_id}
        c = 0
        for e in events:
            if not isinstance(e, dict) or e.get("event_type") != "tool_call":
                continue
            if e.get("session_id") not in sess_ids:
                continue
            ts = _parse_dt(e.get("created_at") or e.get("occurred_at"))
            if ts and cutoff <= ts <= now_dt:
                c += 1
        return c

    picked = None
    for k in sorted(active_keys, key=lambda r: (r.get("last_used_at") or r.get("updated_at") or r.get("created_at") or ""), reverse=True):
        q = k.get("quota_ops_per_minute")
        if isinstance(q, int) and q > 0 and _rolling_ops_count(k["id"]) >= q:
            continue
        picked = k
        break
    if not picked:
        _append_reqlog("browser_snapshot", None, None, "error", (time.time() - t0) * 1000, "RATE_LIMIT")
        return _err("RATE_LIMIT", "Quota exceeded: too many tool operations in the last 60 seconds.")
    api_key_id = picked["id"]

    # find active session
    sess = None
    for s in sessions:
        if not isinstance(s, dict):
            continue
        if s.get("api_key_id") != api_key_id or s.get("status") != "active":
            continue
        exp = _parse_dt(s.get("expires_at"))
        if exp and exp <= now_dt:
            continue
        sess = s
        break
    if not sess:
        _append_reqlog("browser_snapshot", api_key_id, None, "error", (time.time() - t0) * 1000, "NOT_FOUND")
        return _err("NOT_FOUND", "There is no active page (session expired or closed).")

    # active tab must exist and be open
    tab = None
    if sess.get("active_tab_id"):
        tab = next((t for t in tabs if isinstance(t, dict) and t.get("id") == sess.get("active_tab_id")), None)
    if not tab:
        _append_reqlog("browser_snapshot", api_key_id, sess.get("id"), "error", (time.time() - t0) * 1000, "NOT_FOUND")
        return _err("NOT_FOUND", "There is no active page (no active tab).")
    if tab.get("status") != "open":
        _log_tool_call(events, sess.get("id"), tab.get("id"), "error",
                       "No tool may operate on a tab whose status != 'open'.",
                       {"tool": "browser_snapshot", "params": {}})
        _save("browser_events.json", events)
        _append_reqlog("browser_snapshot", api_key_id, sess.get("id"), "error", (time.time() - t0) * 1000, "CONFLICT")
        return _err("CONFLICT", "Page cannot be snapshotted in its current state (requires tab status='open').")

    # create snapshot artifact
    art_id = _new_id("cfpw_art")
    created = now_dt
    snapshot_tree = {
        "version": 1,
        "url": tab.get("current_url"),
        "generated_at": _iso(now_dt),
        "nodes": [
            {"role": "document", "name": tab.get("title") or "Document", "children": []}
        ]
    }
    art = {
        "id": art_id,
        "session_id": sess.get("id"),
        "tab_id": tab.get("id"),
        "artifact_type": "accessibility_snapshot",
        "status": "creating",
        "mime_type": "application/json",
        "byte_size": 0,
        "storage_url": None,
        "content": snapshot_tree,
        "screenshot_format": None,
        "target_element": None,
        "target_ref": None,
        "created_at": _iso(created),
        "updated_at": _iso(created),
        "ready_at": None,
    }
    artifacts.append(art)

    # transition to ready
    art["byte_size"] = len(json.dumps(snapshot_tree, ensure_ascii=False).encode("utf-8"))
    art["status"] = "ready"
    art["ready_at"] = _iso(now_dt)
    art["updated_at"] = _iso(now_dt)

    _log_tool_call(events, sess.get("id"), tab.get("id"), "info", "Accessibility snapshot captured.",
                   {"tool": "browser_snapshot", "params": {}, "artifact_id": art_id})

    sess["last_activity_at"] = _iso(now_dt)
    sess["updated_at"] = _iso(now_dt)
    picked["last_used_at"] = _iso(now_dt)
    picked["updated_at"] = _iso(now_dt)

    _save("browser_artifacts.json", artifacts)
    _save("browser_events.json", events)
    _save("browser_sessions.json", sessions)
    _save("api_keys.json", api_keys)

    _append_reqlog("browser_snapshot", api_key_id, sess.get("id"), "ok", (time.time() - t0) * 1000, None)
    return {"artifact": art, "snapshot": snapshot_tree}

def browser_click(element, ref, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0321000" if __import__("os").path.isdir("./environment_mix/0321000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo is not None else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo is not None else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _append_reqlog(endpoint, api_key_id, session_id, status, latency_ms, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _new_id("cfpw_req"),
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "session_id": session_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int(latency_ms),
            "created_at": _iso(_utcnow()),
        })
        _save("request_logs.json", logs)

    def _log_tool_call(events_rows, session_id, tab_id, severity, message, payload, occurred_dt):
        row = {
            "id": _new_id("cfpw_evt"),
            "session_id": session_id,
            "tab_id": tab_id,
            "event_type": "tool_call",
            "severity": severity,
            "message": message,
            "payload": payload,
            "occurred_at": _iso(occurred_dt),
            "created_at": _iso(_utcnow()),
            "updated_at": _iso(_utcnow()),
        }
        events_rows.append(row)
        return row

    def _quota_ops_exceeded(key_row, sessions_rows, events_rows, now_dt):
        quota = key_row.get("quota_ops_per_minute")
        if not isinstance(quota, int) or quota < 1:
            return False, quota, 0
        win_start = now_dt - datetime.timedelta(seconds=60)
        sess_ids = {s.get("id") for s in sessions_rows if isinstance(s, dict) and s.get("api_key_id") == key_row.get("id")}
        count = 0
        for ev in events_rows:
            if not isinstance(ev, dict) or ev.get("event_type") != "tool_call":
                continue
            if ev.get("session_id") not in sess_ids:
                continue
            dt = _parse_dt(ev.get("occurred_at")) or _parse_dt(ev.get("created_at"))
            if dt is None:
                continue
            if dt >= win_start:
                count += 1
        return count >= quota, quota, count

    t0 = time.time()
    now = _utcnow()

    # Validation: required strings; relax ref format (the datastore shows refs with spaces/quotes/>> etc).
    if not isinstance(element, str) or not element.strip():
        return _err("VALIDATION_ERROR", "Parameter 'element' must be a non-empty string.")
    if not isinstance(ref, str) or not ref.strip():
        return _err("VALIDATION_ERROR", "Parameter 'ref' must be a non-empty string.")
    if len(ref) > 4000:
        return _err("VALIDATION_ERROR", "Parameter 'ref' is too long.")

    api_keys = _load("api_keys.json")
    sessions = _load("browser_sessions.json")
    tabs = _load("browser_tabs.json")
    events = _load("browser_events.json")

    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active" and isinstance(k.get("id"), str)]
    if not active_keys:
        _append_reqlog("browser_click", None, None, "error", (time.time() - t0) * 1000, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "All tool calls require an api_key in status='active'.")

    chosen_key = None
    chosen_sess = None
    for k in active_keys:
        for s in sessions:
            if not isinstance(s, dict):
                continue
            if s.get("api_key_id") != k.get("id"):
                continue
            if s.get("status") != "active":
                continue
            exp = _parse_dt(s.get("expires_at"))
            if exp is not None and exp <= now:
                continue
            chosen_key = k
            chosen_sess = s
            break
        if chosen_sess:
            break

    if not chosen_sess:
        _append_reqlog("browser_click", active_keys[0].get("id"), None, "error", (time.time() - t0) * 1000, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Session/page is unavailable (expired/closed).")

    exceeded, quota, used = _quota_ops_exceeded(chosen_key, sessions, events, now)
    if exceeded:
        _log_tool_call(events, chosen_sess.get("id"), chosen_sess.get("active_tab_id"), "error",
                       "RATE_LIMIT: quota_ops_per_minute exceeded.",
                       {"tool": "browser_click", "params": {"element": element, "ref": ref}}, now)
        _save("browser_events.json", events)
        _append_reqlog("browser_click", chosen_key.get("id"), chosen_sess.get("id"), "error", (time.time() - t0) * 1000, error_code="RATE_LIMIT")
        return _err("RATE_LIMIT", "Quota enforcement: tool operations exceeded quota_ops_per_minute within a rolling 60s window.",
                    quota_ops_per_minute=quota, used_in_window=used)

    sess_id = chosen_sess.get("id")
    tab_id = chosen_sess.get("active_tab_id")

    active_tab = None
    if tab_id:
        for t in tabs:
            if isinstance(t, dict) and t.get("id") == tab_id and t.get("session_id") == sess_id:
                active_tab = t
                break
    if chosen_sess.get("status") != "active" or not active_tab or active_tab.get("status") != "open":
        _log_tool_call(events, sess_id, tab_id, "error",
                       "No tool may operate on a tab whose status != 'open' or a session whose status != 'active'.",
                       {"tool": "browser_click", "params": {"element": element, "ref": ref}}, now)
        _save("browser_events.json", events)
        _append_reqlog("browser_click", chosen_key.get("id"), sess_id, "error", (time.time() - t0) * 1000, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Session/page is unavailable (expired/closed).")

    _log_tool_call(events, sess_id, tab_id, "info", "Clicked element.",
                   {"tool": "browser_click", "params": {"element": element, "ref": ref}}, now)

    chosen_sess["last_activity_at"] = _iso(now)
    chosen_sess["updated_at"] = _iso(now)
    chosen_key["last_used_at"] = _iso(now)
    chosen_key["updated_at"] = _iso(now)

    _save("browser_sessions.json", sessions)
    _save("api_keys.json", api_keys)
    _save("browser_events.json", events)
    _append_reqlog("browser_click", chosen_key.get("id"), sess_id, "success", (time.time() - t0) * 1000)

    return {"clicked": True, "element": element, "ref": ref, "session_id": sess_id, "tab_id": tab_id}

