        _append_reqlog("browser_hover", None, None, "error", (time.time() - t0) * 1000, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Parameter 'ref' is required and must be a non-empty string.")

    api_keys = _load("api_keys.json")
    sessions = _load("browser_sessions.json")
    tabs = _load("browser_tabs.json")
    events = _load("browser_events.json")

    now_dt = _utcnow()

    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active" and k.get("id")]
    if not active_keys:
        _append_reqlog("browser_hover", None, None, "error", (time.time() - t0) * 1000, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "All tool calls require an api_key in status='active'.")

    def _rolling_ops_count(api_key_id):
        cutoff = now_dt - datetime.timedelta(seconds=60)
        sess_ids = {s.get("id") for s in sessions if isinstance(s, dict) and s.get("api_key_id") == api_key_id}
        c = 0
        for e in events:
            if not isinstance(e, dict) or e.get("event_type") != "tool_call":
                continue
            if e.get("session_id") not in sess_ids:
                continue
            ts = _parse_dt(e.get("created_at") or e.get("occurred_at"))
            if ts and cutoff <= ts <= now_dt:
                c += 1
        return c

    picked = None
    for k in sorted(active_keys, key=lambda r: (r.get("last_used_at") or r.get("updated_at") or r.get("created_at") or ""), reverse=True):
        q = k.get("quota_ops_per_minute")
        if isinstance(q, int) and q > 0 and _rolling_ops_count(k["id"]) >= q:
            continue
        picked = k
        break
    if not picked:
        _append_reqlog("browser_hover", None, None, "error", (time.time() - t0) * 1000, "RATE_LIMIT")
        return _err("RATE_LIMIT", "Quota exceeded: too many tool operations in the last 60 seconds.")
    api_key_id = picked["id"]

    # resolve active session (create implicitly if none)
    sess = None
    for s in sessions:
        if not isinstance(s, dict):
            continue
        if s.get("api_key_id") != api_key_id or s.get("status") != "active":
            continue
        exp = _parse_dt(s.get("expires_at"))
        if exp and exp <= now_dt:
            continue
        sess = s
        break
    if not sess:
        # create implicit session if allowed
        cutoff = now_dt - datetime.timedelta(seconds=60)
        created_count = 0
        for s in sessions:
            if not isinstance(s, dict) or s.get("api_key_id") != api_key_id:
                continue
            ts = _parse_dt(s.get("created_at"))
            if ts and cutoff <= ts <= now_dt:
                created_count += 1
        q_sess = picked.get("quota_sessions_per_minute")
        if isinstance(q_sess, int) and q_sess > 0 and created_count >= q_sess:
            _append_reqlog("browser_hover", api_key_id, None, "error", (time.time() - t0) * 1000, "RATE_LIMIT")
            return _err("RATE_LIMIT", "Quota exceeded: too many new sessions in the last 60 seconds.")
        sid = _new_id("cfpw_sess")
        expires = now_dt + datetime.timedelta(seconds=int(picked.get("quota_max_session_seconds") or 300))
        sess = {
            "id": sid,
            "api_key_id": api_key_id,
            "status": "active",
            "browser_channel": "chromium",
            "worker_region": None,
            "installed_at": None,
            "active_tab_id": None,
            "default_viewport_width": 1280,
            "default_viewport_height": 720,
            "last_activity_at": _iso(now_dt),
            "expires_at": _iso(expires),
            "closed_at": None,
            "created_at": _iso(now_dt),
            "updated_at": _iso(now_dt),
        }
        sessions.append(sess)
        _save("browser_sessions.json", sessions)

    # resolve active tab and require it open
    tab = None
    if sess.get("active_tab_id"):
        tab = next((t for t in tabs if isinstance(t, dict) and t.get("id") == sess.get("active_tab_id")), None)
    if not tab or tab.get("status") != "open":
        _log_tool_call(events, sess.get("id"), tab.get("id") if tab else None, "error",
                       "No tool may operate on a tab whose status != 'open' or a session whose status != 'active'.",
                       {"tool": "browser_hover", "params": {"element": element, "ref": ref}})
        _save("browser_events.json", events)
        _append_reqlog("browser_hover", api_key_id, sess.get("id"), "error", (time.time() - t0) * 1000, "NOT_FOUND")
        return _err("NOT_FOUND", "There is no active page/session available (missing active open tab).")

    # record tool_call
    _log_tool_call(events, sess.get("id"), tab.get("id"), "info", "Hovered element.", {"tool": "browser_hover", "params": {"element": element, "ref": ref}})
    sess["last_activity_at"] = _iso(now_dt)
    sess["updated_at"] = _iso(now_dt)
    picked["last_used_at"] = _iso(now_dt)
    picked["updated_at"] = _iso(now_dt)

    _save("browser_events.json", events)
    _save("browser_sessions.json", sessions)
    _save("api_keys.json", api_keys)

    _append_reqlog("browser_hover", api_key_id, sess.get("id"), "ok", (time.time() - t0) * 1000, None)
    return {"hovered": True, "element": element, "ref": ref}

def browser_type(element, ref, text, submit=None, slowly=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0321000" if __import__("os").path.isdir("./environment_mix/0321000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "browser_type"

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if not isinstance(dt, datetime.datetime):
            dt = _utcnow()
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            ss = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(ss)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        import secrets
        return f"{prefix}_01H{secrets.token_hex(9).upper()}"

    def _append_reqlog(api_key_id, session_id, status, latency_ms, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": _new_id("cfpw_req"),
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "session_id": session_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int(latency_ms),
            "created_at": _iso(_utcnow()),
        })
        _save("request_logs.json", logs)

    # Validate required args
    if not isinstance(element, str) or not element:
        latency = (time.time() - t0) * 1000
        _append_reqlog(None, None, "error", latency, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Parameter 'element' is required and must be a non-empty string.")
    if not isinstance(ref, str) or not ref:
        latency = (time.time() - t0) * 1000
        _append_reqlog(None, None, "error", latency, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Parameter 'ref' is required and must be a non-empty string.")
    if not isinstance(text, str):
        latency = (time.time() - t0) * 1000
        _append_reqlog(None, None, "error", latency, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Parameter 'text' is required and must be a string.")
    if submit is not None and not isinstance(submit, bool):
        latency = (time.time() - t0) * 1000
        _append_reqlog(None, None, "error", latency, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Parameter 'submit' must be a boolean when provided.")
    if slowly is not None and not isinstance(slowly, bool):
        latency = (time.time() - t0) * 1000
        _append_reqlog(None, None, "error", latency, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Parameter 'slowly' must be a boolean when provided.")

    # Defaults per business rule
    eff_submit = bool(submit) if submit is not None else False
    eff_slowly = bool(slowly) if slowly is not None else False

    api_keys = _load("api_keys.json")
    sessions = _load("browser_sessions.json")
    tabs = _load("browser_tabs.json")
    events = _load("browser_events.json")
    now = _utcnow()

    # Resolve context
    api_key = None
    session = None
    for k in api_keys if isinstance(api_keys, list) else []:
        if k.get("status") != "active":
            continue
        for s in sessions if isinstance(sessions, list) else []:
            if s.get("api_key_id") == k.get("id") and s.get("status") == "active":
                exp = _parse_dt(s.get("expires_at"))
                if exp is not None and exp <= now:
                    continue
                api_key = k
                session = s
                break
        if api_key:
            break

    if api_key is None:
        # fall back: any active key
        for k in api_keys if isinstance(api_keys, list) else []:
            if k.get("status") == "active":
                api_key = k
                break

    if api_key is None:
        latency = (time.time() - t0) * 1000
        _append_reqlog(None, None, "error", latency, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active api_key is available to authorize this operation.")

    if session is None:
        # Create implicit session and tab
        created = now
        expires = now + datetime.timedelta(seconds=int(api_key.get("quota_max_session_seconds") or 300))
        session = {
            "id": _new_id("cfpw_sess"),
            "api_key_id": api_key.get("id"),
            "status": "active",
            "browser_channel": "chromium",
            "worker_region": None,
            "installed_at": None,
            "active_tab_id": None,
            "default_viewport_width": 1280,
            "default_viewport_height": 720,
            "last_activity_at": _iso(now),
            "expires_at": _iso(expires),
            "closed_at": None,
            "created_at": _iso(created),
            "updated_at": _iso(created),
        }
        tab = {
            "id": _new_id("cfpw_tab"),
            "session_id": session["id"],
            "tab_index": 0,
            "status": "open",
            "current_url": None,
            "title": None,
            "viewport_width": session["default_viewport_width"],
            "viewport_height": session["default_viewport_height"],
            "history_length": 0,
            "history_position": 0,
            "created_at": _iso(created),
            "updated_at": _iso(created),
            "closed_at": None,
        }
        session["active_tab_id"] = tab["id"]
        sessions.append(session)
        tabs.append(tab)
        _save("browser_sessions.json", sessions)
        _save("browser_tabs.json", tabs)

    # Validate session/tab active/open
    tab_row = None
    for t in tabs if isinstance(tabs, list) else []:
        if t.get("id") == session.get("active_tab_id") and t.get("session_id") == session.get("id"):
            tab_row = t
            break

    if session.get("status") != "active":
        # Record error tool_call where possible
        evt = {
            "id": _new_id("cfpw_evt"),
            "session_id": session.get("id"),
            "tab_id": session.get("active_tab_id"),
            "event_type": "tool_call",
            "severity": "error",
            "message": "browser_type rejected: session is not active.",
            "payload": {"tool": endpoint, "element": element, "ref": ref, "text": text, "submit": eff_submit, "slowly": eff_slowly},
            "occurred_at": _iso(now),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        if isinstance(events, list):
            events.append(evt)
            _save("browser_events.json", events)
        latency = (time.time() - t0) * 1000
        _append_reqlog(api_key.get("id"), session.get("id"), "error", latency, "CONFLICT")
        return _err("CONFLICT", "No tool may operate on a session whose status != 'active'.")

    if not tab_row or tab_row.get("status") != "open":
        evt = {
            "id": _new_id("cfpw_evt"),
            "session_id": session.get("id"),
            "tab_id": session.get("active_tab_id"),
            "event_type": "tool_call",
            "severity": "error",
            "message": "browser_type rejected: active tab is not open.",
            "payload": {"tool": endpoint, "element": element, "ref": ref, "text": text, "submit": eff_submit, "slowly": eff_slowly},
            "occurred_at": _iso(now),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        if isinstance(events, list):
            events.append(evt)
            _save("browser_events.json", events)
        latency = (time.time() - t0) * 1000
        _append_reqlog(api_key.get("id"), session.get("id"), "error", latency, "CONFLICT")
        return _err("CONFLICT", "No tool may operate on a tab whose status != 'open'.")

    # Quota enforcement: ops/min
    window_start = now - datetime.timedelta(seconds=60)
    key_sess_ids = {s.get("id") for s in sessions if isinstance(sessions, list) and s.get("api_key_id") == api_key.get("id")}
    tool_calls_60s = 0
    for e in events if isinstance(events, list) else []:
        if e.get("event_type") != "tool_call":
            continue
        if e.get("session_id") not in key_sess_ids:
            continue
        occ = _parse_dt(e.get("occurred_at")) or _parse_dt(e.get("created_at"))
        if occ and occ >= window_start:
            tool_calls_60s += 1
    if tool_calls_60s >= int(api_key.get("quota_ops_per_minute") or 0):
        latency = (time.time() - t0) * 1000
        _append_reqlog(api_key.get("id"), session.get("id"), "error", latency, "RATE_LIMIT")
        return _err("RATE_LIMIT", "Tool operation rate limit exceeded for this api key (quota_ops_per_minute).")

    # Record tool_call event including effective booleans
    evt = {
        "id": _new_id("cfpw_evt"),
        "session_id": session.get("id"),
        "tab_id": tab_row.get("id"),
        "event_type": "tool_call",
        "severity": "info",
        "message": "Typed text into element.",
        "payload": {"tool": endpoint, "element": element, "ref": ref, "text": text, "submit": eff_submit, "slowly": eff_slowly},
        "occurred_at": _iso(now),
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    events.append(evt)
    _save("browser_events.json", events)

    # Update session activity
    for s in sessions if isinstance(sessions, list) else []:
        if s.get("id") == session.get("id"):
            s["last_activity_at"] = _iso(now)
            s["updated_at"] = _iso(now)
            break
    _save("browser_sessions.json", sessions)

    # Update api key last_used_at
    for k in api_keys if isinstance(api_keys, list) else []:
        if k.get("id") == api_key.get("id"):
            k["last_used_at"] = _iso(now)
            k["updated_at"] = _iso(now)
            break
    _save("api_keys.json", api_keys)

    latency = (time.time() - t0) * 1000
    _append_reqlog(api_key.get("id"), session.get("id"), "ok", latency, None)
    return {
        "status": "ok",
        "session_id": session.get("id"),
        "tab_id": tab_row.get("id"),
        "typed": {"element": element, "ref": ref, "text": text, "submit": eff_submit, "slowly": eff_slowly},
        "event_id": evt.get("id"),
    }

