    _save("browser_sessions.json", sessions)
    _save("api_keys.json", api_keys)

    _append_reqlog("browser_select_option", api_key_id, sess.get("id"), "ok", (time.time() - t0) * 1000, None)
    return {"selected": True, "values": values, "element": element, "ref": ref}

def browser_tab_list(sessionId, status=None, limit=None, cursor=None, sortBy=None, sortOrder=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0321000" if __import__("os").path.isdir("./environment_mix/0321000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "browser_tab_list"

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if not isinstance(dt, datetime.datetime):
            dt = _utcnow()
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _new_id(prefix):
        import secrets
        return f"{prefix}_01H{secrets.token_hex(9).upper()}"

    def _append_reqlog(api_key_id, session_id, status_s, latency_ms, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": _new_id("cfpw_req"),
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "session_id": session_id,
            "status": status_s,
            "error_code": error_code,
            "latency_ms": int(latency_ms),
            "created_at": _iso(_utcnow()),
        })
        _save("request_logs.json", logs)

    # Validation (relaxed to not reject datastore-mismatched ids seen in audit;
    # accept any non-empty string as sessionId even if it doesn't match vendor pattern)
    if not isinstance(sessionId, str) or not sessionId:
        latency = (time.time() - t0) * 1000
        _append_reqlog(None, None, "error", latency, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Parameter 'sessionId' is required and must be a non-empty string.")
    if status is not None:
        if not isinstance(status, str) or status not in ("open", "closing", "closed", "crashed"):
            latency = (time.time() - t0) * 1000
            _append_reqlog(None, sessionId, "error", latency, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Parameter 'status' must be one of: open, closing, closed, crashed.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or not (1 <= limit <= 200):
        latency = (time.time() - t0) * 1000
        _append_reqlog(None, sessionId, "error", latency, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Parameter 'limit' must be an integer between 1 and 200.")
    if cursor is not None and not isinstance(cursor, str):
        latency = (time.time() - t0) * 1000
        _append_reqlog(None, sessionId, "error", latency, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Parameter 'cursor' must be a string when provided.")
    if sortBy is None:
        sortBy = "tab_index"
    if sortOrder is None:
        sortOrder = "asc"
    if sortBy not in ("tab_index", "created_at", "updated_at"):
        latency = (time.time() - t0) * 1000
        _append_reqlog(None, sessionId, "error", latency, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Parameter 'sortBy' must be one of: tab_index, created_at, updated_at.")
    if sortOrder not in ("asc", "desc"):
        latency = (time.time() - t0) * 1000
        _append_reqlog(None, sessionId, "error", latency, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Parameter 'sortOrder' must be one of: asc, desc.")

    api_keys = _load("api_keys.json")
    sessions = _load("browser_sessions.json")
    tabs = _load("browser_tabs.json")
    now = _utcnow()

    # Resolve api_key from session ownership if possible; otherwise any active key (ambient).
    sess_row = None
    if isinstance(sessions, list):
        for s in sessions:
            if s.get("id") == sessionId:
                sess_row = s
                break

    api_key_row = None
    if sess_row and isinstance(api_keys, list):
        for k in api_keys:
            if k.get("id") == sess_row.get("api_key_id"):
                api_key_row = k
                break
    if api_key_row is None and isinstance(api_keys, list):
        for k in api_keys:
            if k.get("status") == "active":
                api_key_row = k
                break

    if api_key_row is None or api_key_row.get("status") != "active":
        latency = (time.time() - t0) * 1000
        _append_reqlog(api_key_row.get("id") if api_key_row else None, sessionId, "error", latency, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "All tool calls require an api_key in status='active'.")

    if not sess_row:
        # For read/list endpoints, return NOT_FOUND if session truly doesn't exist per tool description
        latency = (time.time() - t0) * 1000
        _append_reqlog(api_key_row.get("id"), sessionId, "error", latency, "NOT_FOUND")
        return _err("NOT_FOUND", "Session does not exist.")

    # If session is closed/expired, tabs may still exist in datastore; do not error for list.
    # Return tabs belonging to session, ordered and paginated.
    result = [t for t in (tabs if isinstance(tabs, list) else []) if t.get("session_id") == sessionId]
    if status is not None:
        result = [t for t in result if t.get("status") == status]

    reverse = (sortOrder == "desc")
    def _sort_key(r):
        if sortBy == "tab_index":
            try:
                return int(r.get("tab_index") if r.get("tab_index") is not None else 0)
            except Exception:
                return 0
        return r.get(sortBy) or ""
    result.sort(key=_sort_key, reverse=reverse)

    start = 0
    if cursor:
        # cursor is the last seen tab id; start after it
        for i, t in enumerate(result):
            if t.get("id") == cursor:
                start = i + 1
                break

    page = result[start:start + limit]
    next_cursor = None
    has_more = start + limit < len(result)
    if has_more and page:
        next_cursor = page[-1].get("id")

    latency = (time.time() - t0) * 1000
    _append_reqlog(api_key_row.get("id"), sessionId, "ok", latency, None)

    return {
        "tabs": page,
        "metadata": {
            "session_id": sessionId,
            "total": len(result),
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort_by": sortBy,
            "sort_order": sortOrder,
            "status_filter": status,
        },
    }

def browser_tab_new(url=None, **_extra):
    import json, os, datetime, time, urllib.parse
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0321000" if __import__("os").path.isdir("./environment_mix/0321000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "browser_tab_new"

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if not isinstance(dt, datetime.datetime):
            dt = _utcnow()
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            ss = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(ss)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _is_abs_url(u):
        try:
            p = urllib.parse.urlparse(u)
            return p.scheme in ("http", "https") and bool(p.netloc)
        except Exception:
            return False

    def _new_id(prefix):
        import secrets
        return f"{prefix}_01H{secrets.token_hex(9).upper()}"

    def _append_reqlog(api_key_id, session_id, status_s, latency_ms, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": _new_id("cfpw_req"),
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "session_id": session_id,
            "status": status_s,
            "error_code": error_code,
            "latency_ms": int(latency_ms),
            "created_at": _iso(_utcnow()),
        })
        _save("request_logs.json", logs)

    # Validate url if provided
    if url is not None:
        if not isinstance(url, str) or not url or not _is_abs_url(url):
            latency = (time.time() - t0) * 1000
            _append_reqlog(None, None, "error", latency, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Parameter 'url' must be a valid absolute URL (http/https) when provided.")

    api_keys = _load("api_keys.json")
    sessions = _load("browser_sessions.json")
    tabs = _load("browser_tabs.json")
    events = _load("browser_events.json")
    now = _utcnow()

    # Resolve active api key
    api_key = None
    for k in api_keys if isinstance(api_keys, list) else []:
        if k.get("status") == "active":
            api_key = k
            break
    if api_key is None:
        latency = (time.time() - t0) * 1000
        _append_reqlog(None, None, "error", latency, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "All tool calls require an api_key in status='active'.")

    # Resolve or create active session
    session = None
    for s in sessions if isinstance(sessions, list) else []:
        if s.get("api_key_id") == api_key.get("id") and s.get("status") == "active":
            exp = _parse_dt(s.get("expires_at"))
            if exp is not None and exp <= now:
                continue
            session = s
            break
    if session is None:
        created = now
        expires = now + datetime.timedelta(seconds=int(api_key.get("quota_max_session_seconds") or 300))
        session = {
            "id": _new_id("cfpw_sess"),
            "api_key_id": api_key.get("id"),
            "status": "active",
            "browser_channel": "chromium",
            "worker_region": None,
            "installed_at": None,
            "active_tab_id": None,
            "default_viewport_width": 1280,
            "default_viewport_height": 720,
            "last_activity_at": _iso(now),
            "expires_at": _iso(expires),
            "closed_at": None,
            "created_at": _iso(created),
            "updated_at": _iso(created),
        }
        sessions.append(session)
        _save("browser_sessions.json", sessions)

    # Enforce max tabs per session: count open/closing tabs for index semantics
    existing_tabs = [t for t in (tabs if isinstance(tabs, list) else []) if t.get("session_id") == session.get("id") and t.get("status") in ("open", "closing")]
    quota_max_tabs = int(api_key.get("quota_max_tabs") or 1)
    if len(existing_tabs) >= quota_max_tabs:
        latency = (time.time() - t0) * 1000
        _append_reqlog(api_key.get("id"), session.get("id"), "error", latency, "QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Tab creation exceeds quota_max_tabs for this api key/session.")

    # Determine next available tab_index (only open/closing count for semantics)
    next_idx = 0
    if existing_tabs:
        next_idx = max(int(t.get("tab_index") or 0) for t in existing_tabs) + 1

    tab = {
        "id": _new_id("cfpw_tab"),
        "session_id": session.get("id"),
        "tab_index": next_idx,
        "status": "open",
        "current_url": None,
        "title": None,
        "viewport_width": int(session.get("default_viewport_width") or 1280),
        "viewport_height": int(session.get("default_viewport_height") or 720),
        "history_length": 0,
        "history_position": 0,
        "created_at": _iso(now),
        "updated_at": _iso(now),
        "closed_at": None,
    }
    if url is not None:
        tab["current_url"] = url
        tab["history_length"] = 1
        tab["history_position"] = 1

    if not isinstance(tabs, list):
        tabs = []
    tabs.append(tab)
    _save("browser_tabs.json", tabs)

    # Set as active tab
    session["active_tab_id"] = tab["id"]
    session["last_activity_at"] = _iso(now)
    session["updated_at"] = _iso(now)
    _save("browser_sessions.json", sessions)

    # Record tool_call event (and optionally a minimal network_request if url provided)
    if not isinstance(events, list):
        events = []
    tool_evt = {
        "id": _new_id("cfpw_evt"),
        "session_id": session.get("id"),
        "tab_id": tab.get("id"),
        "event_type": "tool_call",
        "severity": "info",
        "message": "Created new tab.",
        "payload": {"tool": endpoint, "url": url, "tab_index": next_idx, "tab_id": tab.get("id")},
        "occurred_at": _iso(now),
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    events.append(tool_evt)
    if url is not None:
        net_evt = {
            "id": _new_id("cfpw_evt"),
            "session_id": session.get("id"),
            "tab_id": tab.get("id"),
            "event_type": "network_request",
            "severity": "info",
            "message": "Main document request.",
            "payload": {"url": url, "method": "GET", "resource_type": "document", "status": 200},
            "occurred_at": _iso(now),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        events.append(net_evt)
    _save("browser_events.json", events)

    # Update api key last_used_at
    for k in api_keys if isinstance(api_keys, list) else []:
        if k.get("id") == api_key.get("id"):
            k["last_used_at"] = _iso(now)
            k["updated_at"] = _iso(now)
            break
    _save("api_keys.json", api_keys)

    latency = (time.time() - t0) * 1000
    _append_reqlog(api_key.get("id"), session.get("id"), "ok", latency, None)
    return {"session": session, "active_tab": tab}

def browser_tab_close(index=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0321000" if __import__("os").path.isdir("./environment_mix/0321000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        return f"{prefix}_01{int(time.time()*1000)}{os.getpid()}"

    def _append_reqlog(endpoint, api_key_id, session_id, status, latency_ms, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _new_id("cfpw_req"),
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "session_id": session_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int(latency_ms),
            "created_at": _iso(_utcnow()),
        })
        _save("request_logs.json", logs)

    def _log_tool_call(events_rows, session_id, tab_id, severity, message, payload):
        now_dt = _utcnow()
        row = {
            "id": _new_id("cfpw_evt"),
            "session_id": session_id,
            "tab_id": tab_id,
            "event_type": "tool_call",
            "severity": severity,
            "message": message,
            "payload": payload,
            "occurred_at": _iso(now_dt),
            "created_at": _iso(now_dt),
            "updated_at": _iso(now_dt),
        }
        events_rows.append(row)

    # validate index if provided; schema uses "number" but business rule says int>=0
    if index is not None:
        if isinstance(index, bool):
            _append_reqlog("browser_tab_close", None, None, "error", (time.time() - t0) * 1000, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "index must be an integer >= 0.")
        if isinstance(index, float) and index.is_integer():
            index = int(index)
        if not isinstance(index, int) or index < 0:
            _append_reqlog("browser_tab_close", None, None, "error", (time.time() - t0) * 1000, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "index must be an integer >= 0.")

    api_keys = _load("api_keys.json")
    sessions = _load("browser_sessions.json")
    tabs = _load("browser_tabs.json")
    events = _load("browser_events.json")

    now_dt = _utcnow()

    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active" and k.get("id")]
    if not active_keys:
        _append_reqlog("browser_tab_close", None, None, "error", (time.time() - t0) * 1000, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "All tool calls require an api_key in status='active'.")

    def _rolling_ops_count(api_key_id):
        cutoff = now_dt - datetime.timedelta(seconds=60)
        sess_ids = {s.get("id") for s in sessions if isinstance(s, dict) and s.get("api_key_id") == api_key_id}
        c = 0
        for e in events:
            if not isinstance(e, dict) or e.get("event_type") != "tool_call":
                continue
            if e.get("session_id") not in sess_ids:
                continue
            ts = _parse_dt(e.get("created_at") or e.get("occurred_at"))
            if ts and cutoff <= ts <= now_dt:
                c += 1
        return c

    picked = None
    for k in sorted(active_keys, key=lambda r: (r.get("last_used_at") or r.get("updated_at") or r.get("created_at") or ""), reverse=True):
        q = k.get("quota_ops_per_minute")
        if isinstance(q, int) and q > 0 and _rolling_ops_count(k["id"]) >= q:
            continue
        picked = k
        break
    if not picked:
        _append_reqlog("browser_tab_close", None, None, "error", (time.time() - t0) * 1000, "RATE_LIMIT")
        return _err("RATE_LIMIT", "Quota exceeded: too many tool operations in the last 60 seconds.")
    api_key_id = picked["id"]

    # resolve active session (must exist; may create implicitly if none)
    sess = None
    for s in sessions:
        if not isinstance(s, dict):
            continue
        if s.get("api_key_id") != api_key_id or s.get("status") != "active":
            continue
        exp = _parse_dt(s.get("expires_at"))
        if exp and exp <= now_dt:
            continue
        sess = s
        break
    if not sess:
        _append_reqlog("browser_tab_close", api_key_id, None, "error", (time.time() - t0) * 1000, "NOT_FOUND")
        return _err("NOT_FOUND", "Session is unavailable (expired/closed).")

    # choose tab to close
    tab = None
    if index is None:
        if sess.get("active_tab_id"):
            tab = next((t for t in tabs if isinstance(t, dict) and t.get("id") == sess.get("active_tab_id")), None)
    else:
        tab = next((t for t in tabs if isinstance(t, dict) and t.get("session_id") == sess.get("id") and t.get("tab_index") == index), None)

    if not tab:
        _log_tool_call(events, sess.get("id"), None, "error", "No tab exists at the requested index (or no active tab).",
                       {"tool": "browser_tab_close", "params": {"index": index}})
        _save("browser_events.json", events)
        _append_reqlog("browser_tab_close", api_key_id, sess.get("id"), "error", (time.time() - t0) * 1000, "NOT_FOUND")
        return _err("NOT_FOUND", "No tab exists at the requested index (or no active tab).")

    # must only operate on open tab and active session
    if sess.get("status") != "active":
        _log_tool_call(events, sess.get("id"), tab.get("id"), "error",
                       "No tool may operate on a session whose status != 'active'.",
                       {"tool": "browser_tab_close", "params": {"index": index}})
        _save("browser_events.json", events)
        _append_reqlog("browser_tab_close", api_key_id, sess.get("id"), "error", (time.time() - t0) * 1000, "NOT_FOUND")
        return _err("NOT_FOUND", "Session is unavailable (expired/closed).")

    if tab.get("status") != "open":
        _log_tool_call(events, sess.get("id"), tab.get("id"), "error",
                       "No tool may operate on a tab whose status != 'open'.",
                       {"tool": "browser_tab_close", "params": {"index": index}})
        _save("browser_events.json", events)
        _append_reqlog("browser_tab_close", api_key_id, sess.get("id"), "error", (time.time() - t0) * 1000, "CONFLICT")
        return _err("CONFLICT", "Tab is not in a closable state (requires status='open').")

    # close: open -> closing -> closed
    tab["status"] = "closing"
    tab["updated_at"] = _iso(now_dt)
    tab["status"] = "closed"
    tab["closed_at"] = _iso(now_dt)
    tab["updated_at"] = _iso(now_dt)

    # if active tab was closed, select the lowest tab_index still open else null
    if sess.get("active_tab_id") == tab.get("id"):
        remaining = [t for t in tabs if isinstance(t, dict) and t.get("session_id") == sess.get("id") and t.get("status") == "open"]
        remaining.sort(key=lambda t: t.get("tab_index", 10**9))
        sess["active_tab_id"] = remaining[0].get("id") if remaining else None

    # update session activity + record tool_call
    _log_tool_call(events, sess.get("id"), tab.get("id"), "info", "Tab closed.", {"tool": "browser_tab_close", "params": {"index": index}})
    sess["last_activity_at"] = _iso(now_dt)
    sess["updated_at"] = _iso(now_dt)
    picked["last_used_at"] = _iso(now_dt)
    picked["updated_at"] = _iso(now_dt)

    _save("browser_tabs.json", tabs)
    _save("browser_sessions.json", sessions)
    _save("browser_events.json", events)
    _save("api_keys.json", api_keys)

    _append_reqlog("browser_tab_close", api_key_id, sess.get("id"), "ok", (time.time() - t0) * 1000, None)
