    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = _dt_to_iso(now_dt)

    # Find an existing active session for this key; if none, create implicitly
    active_session = None
    for s in sessions:
        if s.get("api_key_id") == api_key.get("id") and s.get("status") == "active":
            # expire if needed
            exp = _parse_dt(s.get("expires_at"))
            if exp and exp <= now_dt:
                # Transition active->expired (allowed)
                s["status"] = "expired"
                s["updated_at"] = now_iso
                if s.get("closed_at") is None:
                    s["closed_at"] = s.get("closed_at")
                active_session = None
            else:
                active_session = s
            break

    # Enforce quotas if we need to create a new session
    created_session = False
    if active_session is None:
        # Create implicitly per business rules, but enforce sessions/min quota.
        start_dt = _window_60s_start(now_dt)
        sessions_in_window = _count_sessions_in_window(sessions, api_key["id"], start_dt, now_dt)
