    # Enforce ops quota for this call (counts tool_call events). Session_get is still a tool operation.
    start_dt = _window_60s_start(now_dt)
    tool_ops = _count_tool_calls_in_window(events, active_session["id"], start_dt, now_dt)
    if tool_ops >= int(api_key.get("quota_ops_per_minute", 0)):
        return _err("RATE_LIMIT", "Operation rate limit exceeded", limit="quota_ops_per_minute")

    # Record tool_call event (observable dynamics)
    ev_id = _gen_id("evt")
    ev = {
        "id": ev_id,
        "session_id": active_session["id"],
        "tab_id": active_session.get("active_tab_id"),
        "event_type": "tool_call",
        "severity": "info",
        "message": "browser_session_get",
        "payload": {"includeTabs": bool(includeTabs) if includeTabs is not None else False},
        "occurred_at": now_iso,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
