def browser_session_close(reason=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0321000" if __import__("os").path.isdir("./environment_mix/0321000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2).astimezone(datetime.timezone.utc).replace(tzinfo=None)
        except Exception:
            return None

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _window_60s_start(now_dt):
        return now_dt - datetime.timedelta(seconds=60)

    def _count_tool_calls_in_window(events, session_id, start_dt, now_dt):
        c = 0
        for e in events:
            if e.get("session_id") != session_id:
                continue
            if e.get("event_type") != "tool_call":
                continue
            occ = _parse_dt(e.get("occurred_at"))
            if occ and start_dt <= occ <= now_dt:
                c += 1
        return c

    t0 = time.time()

    if reason is not None:
        if not isinstance(reason, str):
            return _err("VALIDATION_ERROR", "reason must be a string")
        if len(reason) > 200:
            return _err("VALIDATION_ERROR", "reason must be at most 200 characters")

    api_keys = _load("api_keys.json")
    sessions = _load("browser_sessions.json")
    tabs = _load("browser_tabs.json")
    events = _load("browser_events.json")

    api_key = None
    for k in api_keys:
        if k.get("status") == "active":
            api_key = k
            break
    if not api_key:
        return _err("UNAUTHORIZED", "No active API key available for this request")

    # Find active session for this key
    session = None
    for s in sessions:
        if s.get("api_key_id") == api_key.get("id") and s.get("status") == "active":
            session = s
            break
    if not session:
        return _err("NOT_FOUND", "No active session to close")

    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now_dt.isoformat() + "Z"

    # Expired sessions are unavailable (but we only picked active); still check expiry
    exp = _parse_dt(session.get("expires_at"))
    if exp and exp <= now_dt:
        # transition active->expired
        session["status"] = "expired"
        session["updated_at"] = now_iso
        _save("browser_sessions.json", sessions)
        return _err("NOT_FOUND", "Session is unavailable (expired)")

    # Enforce ops quota for this call
    start_dt = _window_60s_start(now_dt)
    tool_ops = _count_tool_calls_in_window(events, session["id"], start_dt, now_dt)
    if tool_ops >= int(api_key.get("quota_ops_per_minute", 0)):
        return _err("RATE_LIMIT", "Operation rate limit exceeded", limit="quota_ops_per_minute")

    # Record attempt as tool_call; if we fail later, mark error.
    ev_id = _gen_id("evt")
    tool_event = {
        "id": ev_id,
        "session_id": session["id"],
        "tab_id": session.get("active_tab_id"),
        "event_type": "tool_call",
        "severity": "info",
        "message": "browser_session_close",
        "payload": {"reason": reason} if reason is not None else {},
        "occurred_at": now_iso,
        "created_at": now_iso,
        "updated_at": now_iso,
    }

    # Transition session active -> closing -> closed
    # CONFLICT: in-flight operation. No explicit lock model in schema; interpret as already closing.
    if session.get("status") != "active":
        tool_event["severity"] = "error"
        tool_event["message"] = "browser_session_close failed"
        tool_event["payload"] = {**tool_event.get("payload", {}), "error": "session_not_active"}
        events.append(tool_event)
        _save("browser_events.json", events)
        return _err("CONFLICT", "Session cannot be closed due to an in-flight operation or non-active state")

    session["status"] = "closing"
    session["updated_at"] = now_iso

    # Cascade closure: any open tabs -> closing -> closed
    for t in tabs:
        if t.get("session_id") != session["id"]:
            continue
        if t.get("status") == "open":
            t["status"] = "closing"
            t["updated_at"] = now_iso
        if t.get("status") == "closing":
            t["status"] = "closed"
            t["closed_at"] = now_iso
            t["updated_at"] = now_iso

    session["status"] = "closed"
    session["closed_at"] = now_iso
    session["active_tab_id"] = None
    session["last_activity_at"] = now_iso
    session["updated_at"] = now_iso

    events.append(tool_event)

    api_key["last_used_at"] = now_iso
    api_key["updated_at"] = now_iso

    _save("api_keys.json", api_keys)
    _save("browser_tabs.json", tabs)
    _save("browser_sessions.json", sessions)
    _save("browser_events.json", events)

    return {
        "session": session,
        "meta": {"latency_ms": int((time.time() - t0) * 1000)},
    }

