    session = None
    for s in sessions:
        if s.get("api_key_id") == api_key.get("id") and s.get("status") == "active":
            session = s
            break
    if not session:
        return _err("NOT_FOUND", "Session is unavailable (no active session)")

    now_dt = _now()
    now_iso = now_dt.isoformat() + "Z"

    exp = _parse_dt(session.get("expires_at"))
    if exp and exp <= now_dt:
        session["status"] = "expired"
        session["updated_at"] = now_iso
        _save("browser_sessions.json", sessions)
        return _err("NOT_FOUND", "Session is unavailable (expired)")

    # Enforce ops quota for this call (still a tool op)
    start_dt = _window_60s_start(now_dt)
    tool_ops = _count_tool_calls_in_window(events, session["id"], start_dt, now_dt)
    if tool_ops >= int(api_key.get("quota_ops_per_minute", 0)):
        return _err("RATE_LIMIT", "Operation rate limit exceeded", limit="quota_ops_per_minute")

    # Resolve optional tabIndex -> tab_id
    tab_id_filter = None
    if tabIndex is not None:
        tmatch = None
        for t in tabs:
            if t.get("session_id") == session["id"] and t.get("tab_index") == tabIndex:
                tmatch = t
                break
        if not tmatch:
            # Read with filter matching nothing => empty set, not error (as a list endpoint)
            tab_id_filter = "__none__"
        else:
            tab_id_filter = tmatch.get("id")

    # Cursor handling
    cur = _decode_cursor(cursor) if cursor else None
    after_occurred = None
    after_id = None
    if cur is not None:
        if not isinstance(cur, dict) or cur.get("session_id") != session["id"] or cur.get("order") != order:
            return _err("VALIDATION_ERROR", "cursor is invalid for this request")
        after_occurred = _parse_dt(cur.get("after_occurred_at"))
        after_id = cur.get("after_id")
        if after_occurred is None or not isinstance(after_id, str):
            return _err("VALIDATION_ERROR", "cursor is invalid for this request")

    # Filter events
    filtered = []
    for e in events:
        if e.get("session_id") != session["id"]:
            continue
        if tab_id_filter is not None and tab_id_filter != e.get("tab_id"):
            continue
        if eventType is not None and e.get("event_type") != eventType:
            continue
        if severity is not None and e.get("severity") != severity:
            continue
        occ = _parse_dt(e.get("occurred_at"))
        if occ is None:
            continue
        if since_dt and occ < since_dt:
            continue
        if until_dt and occ > until_dt:
            continue
        filtered.append((occ, e.get("id"), e))

    # Sort
    filtered.sort(key=lambda x: (x[0], x[1] or ""))
    if order == "desc":
        filtered.reverse()

    # Apply cursor (exclusive)
    if after_occurred is not None:
        out = []
        for occ, eid, e in filtered:
            if order == "asc":
                if (occ > after_occurred) or (occ == after_occurred and (eid or "") > after_id):
                    out.append((occ, eid, e))
            else:
                if (occ < after_occurred) or (occ == after_occurred and (eid or "") < after_id):
                    out.append((occ, eid, e))
        filtered = out

    total = len(filtered)
    page = filtered[:limit]
    items = [e for _, _, e in page]
    has_more = total > len(items)

    next_cursor = None
    if has_more and page:
        last_occ, last_id, _ = page[-1]
        next_cursor = _encode_cursor(
            {"session_id": session["id"], "order": order, "after_occurred_at": last_occ.replace(microsecond=0).isoformat() + "Z", "after_id": last_id}
        )

    # Record tool_call event for listing (observability)
    ev = {
        "id": _gen_id("evt"),
        "session_id": session["id"],
        "tab_id": session.get("active_tab_id"),
        "event_type": "tool_call",
        "severity": "info",
        "message": "browser_events_list",
        "payload": {
            "tabIndex": tabIndex,
            "eventType": eventType,
            "severity": severity,
            "since": since,
            "until": until,
            "order": order,
            "limit": limit,
            "cursor": bool(cursor),
        },
        "occurred_at": now_iso,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    events.append(ev)

    session["last_activity_at"] = now_iso
    session["updated_at"] = now_iso
    api_key["last_used_at"] = now_iso
    api_key["updated_at"] = now_iso

    _save("api_keys.json", api_keys)
    _save("browser_sessions.json", sessions)
    _save("browser_events.json", events)

    return {
        "events": items,
        "page": {"limit": limit, "total_matched": total, "has_more": has_more, "next_cursor": next_cursor, "order": order},
        "meta": {"latency_ms": int((time.time() - t0) * 1000)},
    }

def browser_artifacts_list(tabIndex=None, artifactType=None, status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0321000" if __import__("os").path.isdir("./environment_mix/0321000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        return f"{prefix}_01{int(time.time()*1000)}{os.getpid()}"

    def _append_reqlog(endpoint, api_key_id, session_id, status_, latency_ms, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _new_id("cfpw_req"),
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "session_id": session_id,
            "status": status_,
            "error_code": error_code,
            "latency_ms": int(latency_ms),
            "created_at": _iso(_utcnow()),
        })
        _save("request_logs.json", logs)

    def _log_tool_call(events_rows, session_id, tab_id, severity, message, payload):
        now_dt = _utcnow()
        row = {
            "id": _new_id("cfpw_evt"),
            "session_id": session_id,
            "tab_id": tab_id,
            "event_type": "tool_call",
            "severity": severity,
            "message": message,
            "payload": payload,
            "occurred_at": _iso(now_dt),
            "created_at": _iso(now_dt),
            "updated_at": _iso(now_dt),
        }
        events_rows.append(row)

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(c):
        if not isinstance(c, str) or not c:
            return None
        pad = "=" * (-len(c) % 4)
        try:
            raw = base64.urlsafe_b64decode((c + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            return obj if isinstance(obj, dict) else None
        except Exception:
            return None

    # validate inputs
    if tabIndex is not None:
        if not isinstance(tabIndex, int) or tabIndex < 0:
            _append_reqlog("browser_artifacts_list", None, None, "error", (time.time() - t0) * 1000, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "tabIndex must be an integer >= 0.")
    if artifactType is not None and artifactType not in ("screenshot", "pdf", "accessibility_snapshot"):
        _append_reqlog("browser_artifacts_list", None, None, "error", (time.time() - t0) * 1000, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "artifactType must be one of: screenshot, pdf, accessibility_snapshot.")
    if status is not None and status not in ("creating", "ready", "failed", "deleted"):
        _append_reqlog("browser_artifacts_list", None, None, "error", (time.time() - t0) * 1000, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status must be one of: creating, ready, failed, deleted.")
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or not (1 <= limit <= 500):
        _append_reqlog("browser_artifacts_list", None, None, "error", (time.time() - t0) * 1000, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 500.")
    if cursor is not None and not isinstance(cursor, str):
        _append_reqlog("browser_artifacts_list", None, None, "error", (time.time() - t0) * 1000, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cursor must be a string.")

    api_keys = _load("api_keys.json")
    sessions = _load("browser_sessions.json")
    tabs = _load("browser_tabs.json")
    events = _load("browser_events.json")
    artifacts = _load("browser_artifacts.json")

    now_dt = _utcnow()

    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active" and k.get("id")]
    if not active_keys:
        _append_reqlog("browser_artifacts_list", None, None, "error", (time.time() - t0) * 1000, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "All tool calls require an api_key in status='active'.")

    # resolve an active session for some active key (implicit model)
    sess = None
    owning_key = None
    for k in sorted(active_keys, key=lambda r: (r.get("last_used_at") or r.get("updated_at") or r.get("created_at") or ""), reverse=True):
        for s in sessions:
            if not isinstance(s, dict):
                continue
            if s.get("api_key_id") != k.get("id") or s.get("status") != "active":
                continue
            exp = _parse_dt(s.get("expires_at"))
            if exp and exp <= now_dt:
                continue
            sess = s
            owning_key = k
            break
        if sess:
            break
    if not sess:
        _append_reqlog("browser_artifacts_list", None, None, "error", (time.time() - t0) * 1000, "NOT_FOUND")
        return _err("NOT_FOUND", "Session is unavailable (expired/closed).")

    # optional filter by tabIndex -> find tab_id
    tab_id_filter = None
    if tabIndex is not None:
        tab_row = next((t for t in tabs if isinstance(t, dict) and t.get("session_id") == sess.get("id") and t.get("tab_index") == tabIndex), None)
        if not tab_row:
            # read with filters matching nothing returns empty set (not an error)
            tab_id_filter = "__none__"
        else:
            tab_id_filter = tab_row.get("id")

    rows = [a for a in artifacts if isinstance(a, dict) and a.get("session_id") == sess.get("id")]
    if tab_id_filter is not None:
        rows = [a for a in rows if a.get("tab_id") == tab_id_filter]
    if artifactType is not None:
        rows = [a for a in rows if a.get("artifact_type") == artifactType]
    if status is not None:
        rows = [a for a in rows if a.get("status") == status]

    # newest-to-oldest created_at
    rows.sort(key=lambda r: _parse_dt(r.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc), reverse=True)

    start = 0
    if cursor:
        cobj = _decode_cursor(cursor)
        if cobj and cobj.get("last_id"):
            last_id = cobj["last_id"]
            for i, r in enumerate(rows):
                if r.get("id") == last_id:
                    start = i + 1
                    break

    page = rows[start:start + limit]
    has_more = (start + limit) < len(rows)
    next_cursor = _encode_cursor({"last_id": page[-1].get("id")}) if has_more and page else None

    _log_tool_call(events, sess.get("id"), None, "info", "Listed artifacts.",
                   {"tool": "browser_artifacts_list", "params": {"tabIndex": tabIndex, "artifactType": artifactType, "status": status, "limit": limit, "cursor": cursor}})

    sess["last_activity_at"] = _iso(now_dt)
    sess["updated_at"] = _iso(now_dt)
    owning_key["last_used_at"] = _iso(now_dt)
    owning_key["updated_at"] = _iso(now_dt)

    _save("browser_events.json", events)
    _save("browser_sessions.json", sessions)
    _save("api_keys.json", api_keys)

    _append_reqlog("browser_artifacts_list", owning_key.get("id"), sess.get("id"), "ok", (time.time() - t0) * 1000, None)
    return {"artifacts": page, "total": len(rows), "limit": limit, "has_more": has_more, "next_cursor": next_cursor}

def browser_artifact_get(id, includeContent=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0321000" if __import__("os").path.isdir("./environment_mix/0321000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "browser_artifact_get"

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if not isinstance(dt, datetime.datetime):
            dt = _utcnow()
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _new_id(prefix):
        import secrets
        return f"{prefix}_01H{secrets.token_hex(9).upper()}"

    def _append_reqlog(api_key_id, session_id, status_s, latency_ms, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": _new_id("cfpw_req"),
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "session_id": session_id,
            "status": status_s,
            "error_code": error_code,
            "latency_ms": int(latency_ms),
            "created_at": _iso(_utcnow()),
        })
        _save("request_logs.json", logs)

    # Validate
    if not isinstance(id, str) or not id:
        latency = (time.time() - t0) * 1000
        _append_reqlog(None, None, "error", latency, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Parameter 'id' is required and must be a non-empty string.")
    if includeContent is not None and not isinstance(includeContent, bool):
        latency = (time.time() - t0) * 1000
        _append_reqlog(None, None, "error", latency, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Parameter 'includeContent' must be a boolean when provided.")
    inc = bool(includeContent) if includeContent is not None else False

    api_keys = _load("api_keys.json")
    sessions = _load("browser_sessions.json")
    artifacts = _load("browser_artifacts.json")

    # Ambient auth: any active api key
    api_key = None
    for k in api_keys if isinstance(api_keys, list) else []:
        if k.get("status") == "active":
            api_key = k
            break
    if api_key is None:
        latency = (time.time() - t0) * 1000
        _append_reqlog(None, None, "error", latency, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "All tool calls require an api_key in status='active'.")

    # Find artifact (do not misinterpret ids; accept any id and search)
    art = None
    if isinstance(artifacts, list):
        for a in artifacts:
            if a.get("id") == id:
                art = a
                break
    if not art:
        latency = (time.time() - t0) * 1000
        _append_reqlog(api_key.get("id"), None, "error", latency, "NOT_FOUND")
        return _err("NOT_FOUND", "Artifact does not exist.")

    # Visibility: must be visible for the current session context; without explicit session, allow if its owning api_key is active.
    session_id = art.get("session_id")
    session_row = None
    if session_id and isinstance(sessions, list):
        for s in sessions:
            if s.get("id") == session_id:
                session_row = s
                break
    # If session exists, require it belongs to this api_key (best-effort); if not, still allow read when api_key is active
    if session_row and session_row.get("api_key_id") != api_key.get("id"):
        latency = (time.time() - t0) * 1000
        _append_reqlog(api_key.get("id"), session_id, "error", latency, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Caller is not authorized to access this artifact.")

    if art.get("status") != "ready":
        latency = (time.time() - t0) * 1000
        _append_reqlog(api_key.get("id"), session_id, "error", latency, "CONFLICT")
        return _err("CONFLICT", "Artifact is not ready.", status=art.get("status"))

    # Build response
    out = dict(art)
    if not inc:
        out.pop("content", None)

    # Update api key last_used_at
    now = _utcnow()
    for k in api_keys if isinstance(api_keys, list) else []:
        if k.get("id") == api_key.get("id"):
            k["last_used_at"] = _iso(now)
            k["updated_at"] = _iso(now)
            break
    _save("api_keys.json", api_keys)

    latency = (time.time() - t0) * 1000
    _append_reqlog(api_key.get("id"), session_id, "ok", latency, None)
    return {"artifact": out, "includeContent": inc}
